-- ==== BEGIN MIGRATION 20261216000300_account_deactivation_inactive_people.sql (38997 bytes, sha256 9fea5bbb33f75904122e25a0b4477df0760c6867cb4af0cbb599ca49678c7241) ====
-- A12 / D-10. Deactivating an account makes the person INACTIVE for access and routing, not only unable to sign in. ADDITIVE: replaces functions in place
-- (create or replace) and adds three new ones; no table, column, policy or privilege on an existing object changes, and NO DATA CHANGES (nobody's access is
-- altered by running this file; see the optional owner step in docs/launch-p1c-deployment.md for accounts deactivated before today).
--
-- WHY. set_account_status() only updated profiles.account_status. profiles.is_active, which every Sales, Projects, Inventory and Budget access helper joins, was never
-- set to false by any application path, and resolve_approver*() ignored the account altogether, so a leaver stayed selectable and eligible as project manager, team
-- head, member and "last eligible CEO / CTO approver", and stayed the approver of record for every NEW request.
--
-- WHAT.
--   * set_account_status() sets profiles.is_active in the same transaction (false on deactivate, true on reactivate), and refuses to deactivate the last active
--     System Administrator (existing rule, same wording), the only CEO / CTO budget approver of a company, and the only CEO / CTO of a company.
--   * user_is_active(uuid) (internal): the one test "this person's profile is active". resolve_approver, resolve_approver_for_company, resolve_role_holders, the
--     Recovery Leave routing (recovery_eligible_approver_exists, recovery_route_request) and create_initial_approval's role-queue check skip inactive people, so a NEW
--     request goes to the next holder, and a request with nobody left says so in the existing words.
--   * account_deactivation_blockers(uuid) (internal) and account_holdings(uuid) (System Administrator only): what the person still holds, so the screen can show it
--     before the reason is typed. Counts and project REFERENCE CODES only (no project names, amounts or contents).
--   * guard_profiles_self_update() also refuses a person changing their own is_active (the flag now gates access, like account_status).
--
-- WHAT DOES NOT CHANGE. Approvals ALREADY pending on a person stay exactly as they are: nothing is re-routed automatically and there is no re-route action (owner
-- decision). Who may deactivate (System Administrator only), self-deactivation refusal, the reason rules, the audit trail, sign-in blocking (done by the server action
-- through the Admin API), company boundaries, every approval and grant rule. has_role() and the other role checks on the CALLER are unchanged (a banned person cannot
-- sign in; a session already open ends at its token expiry, as before).
--
-- Reactivation restores everything (is_active true again; the person is resolved again from the next request on).
-- ROLLBACK: supabase/manual-sql/deact_90_rollback.sql re-installs the previous definitions of every replaced function (shown by fingerprint).

-- ---------------------------------------------------------------------------------------------------------------------------------------------
-- Internal helpers (not callable by signed-in users: only by the SECURITY DEFINER functions below)
-- ---------------------------------------------------------------------------------------------------------------------------------------------
create or replace function user_is_active(p_user_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (select 1 from profiles where id = p_user_id and is_active);
$$;

revoke all on function user_is_active(uuid) from public, anon, authenticated;

create or replace function account_deactivation_blockers(p_user_id uuid)
returns text[]
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_out text[] := '{}'::text[];
  c record;
begin
  -- the last active System Administrator (same rule and wording as before: checked against active accounts rather than unrevoked grants)
  if exists (select 1 from user_roles where user_id = p_user_id and role = 'sys_admin' and revoked_at is null)
     and not exists (
       select 1 from user_roles ur join profiles p on p.id = ur.user_id
        where ur.role = 'sys_admin' and ur.revoked_at is null and p.account_status = 'active' and p.is_active and ur.user_id <> p_user_id) then
    v_out := v_out || 'Can''t deactivate the last active System Administrator — the system would have nobody left to manage users or roles'::text;
  end if;

  -- the only CEO / CTO approver of project budgets of a company (the "last eligible approver" rule of the access grant rules)
  for c in
    select co.legal_name from pbx_company_grants g join companies co on co.id = g.company_id
     where g.user_id = p_user_id and g.revoked_at is null and 'executive_approver' = any (g.capabilities)
       and not exists (
         select 1 from pbx_company_grants g2 join profiles p2 on p2.id = g2.user_id and p2.is_active
          where g2.company_id = g.company_id and g2.revoked_at is null and g2.user_id <> p_user_id and 'executive_approver' = any (g2.capabilities))
     order by co.legal_name
  loop
    v_out := v_out || format('Can''t deactivate the only CEO / CTO approver of project budgets for %s — give another active person the approver right first', c.legal_name);
  end loop;

  -- the only CEO / CTO of a company (people with nobody above them are routed to "any other CEO / CTO")
  for c in
    select co.legal_name from companies co
     where co.is_active and co.deleted_at is null
       and exists (
         select 1 from user_roles ur
          where ur.user_id = p_user_id and ur.role in ('ceo', 'cto') and ur.revoked_at is null and (ur.company_id is null or ur.company_id = co.id))
       and not exists (
         select 1 from user_roles ur2 join profiles p2 on p2.id = ur2.user_id and p2.is_active
          where ur2.role in ('ceo', 'cto') and ur2.revoked_at is null and (ur2.company_id is null or ur2.company_id = co.id) and ur2.user_id <> p_user_id)
     order by co.legal_name
  loop
    v_out := v_out || format('Can''t deactivate the only CEO or CTO of %s — give another active person that role first', c.legal_name);
  end loop;

  return v_out;
end;
$$;

revoke all on function account_deactivation_blockers(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------------------------------------
-- What the person still holds: System Administrator only. Counts and codes, never contents.
-- ---------------------------------------------------------------------------------------------------------------------------------------------
create or replace function account_holdings(p_user_id uuid)
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_employee uuid;
begin
  if auth.uid() is null or not has_role('sys_admin') then
    raise exception 'Only a System Administrator can see what an account still holds' using errcode = '42501';
  end if;
  select id into v_employee from employees where user_id = p_user_id and deleted_at is null limit 1;
  return jsonb_build_object(
    'blockers', to_jsonb(account_deactivation_blockers(p_user_id)),
    -- approvals assigned to this person that nobody has decided yet: they stay with the person until HR changes who decides
    'pending_approvals', coalesce((
      select jsonb_agg(jsonb_build_object('entity_type', t.entity_type, 'count', t.n) order by t.entity_type)
        from (select a.entity_type::text as entity_type, count(*)::int as n from approvals a
               where a.approver_id = p_user_id and a.decision = 'pending' group by a.entity_type) t), '[]'::jsonb),
    -- live projects (not completed or archived): reference codes only
    'projects_managed', coalesce((
      select jsonb_agg(jsonb_build_object('reference', p.reference, 'role', 'pm') order by p.reference)
        from proj_projects p where p.pm_user_id = p_user_id and p.status not in ('completed', 'archived')), '[]'::jsonb),
    'projects_acting', coalesce((
      select jsonb_agg(jsonb_build_object('reference', p.reference, 'role', 'acting_pm') order by p.reference)
        from proj_project_members m join proj_projects p on p.id = m.project_id
       where m.user_id = p_user_id and m.role = 'acting_pm' and m.removed_at is null and p.status not in ('completed', 'archived')), '[]'::jsonb),
    'teams_headed', coalesce((
      select jsonb_agg(jsonb_build_object('project', p.reference, 'team', t.name) order by p.reference, t.name)
        from proj_teams t join proj_projects p on p.id = t.project_id
       where t.head_user_id = p_user_id and t.removed_at is null and p.status not in ('completed', 'archived')), '[]'::jsonb),
    -- HR roles and module access: which, for which company, never the detail of what the person did with them
    'roles', coalesce((
      select jsonb_agg(jsonb_build_object('role', ur.role::text, 'company', co.legal_name) order by ur.role::text, co.legal_name nulls first)
        from user_roles ur left join companies co on co.id = ur.company_id where ur.user_id = p_user_id and ur.revoked_at is null), '[]'::jsonb),
    'module_access', coalesce((
      select jsonb_agg(jsonb_build_object('module', m.module, 'company', m.company) order by m.module, m.company)
        from (
          select 'Sales' as module, co.legal_name as company from crm_company_grants g join companies co on co.id = g.company_id where g.user_id = p_user_id and g.revoked_at is null
          union all select 'Projects', co.legal_name from proj_company_grants g join companies co on co.id = g.company_id where g.user_id = p_user_id and g.revoked_at is null
          union all select 'Inventory', co.legal_name from inv_company_grants g join companies co on co.id = g.company_id where g.user_id = p_user_id and g.revoked_at is null
          union all select 'Project budgets', co.legal_name from pbx_company_grants g join companies co on co.id = g.company_id where g.user_id = p_user_id and g.revoked_at is null
        ) m), '[]'::jsonb),
    'equipment_held', case when v_employee is null then 0
      else (select count(*)::int from inv_units u where u.employee_id = v_employee and u.custody_kind = 'employee' and u.lifecycle <> 'retired') end
  );
end;
$$;

revoke all on function account_holdings(uuid) from public, anon;
grant execute on function account_holdings(uuid) to authenticated;

-- ---------------------------------------------------------------------------------------------------------------------------------------------
-- set_account_status(): as before, plus is_active in the same step and the new refusals
-- ---------------------------------------------------------------------------------------------------------------------------------------------
create or replace function set_account_status(p_user_id uuid, p_new_status account_status, p_reason text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_current_status account_status;
  v_blockers text[];
begin
  if auth.uid() is null or not has_role('sys_admin') then
    raise exception 'Only a System Administrator may change an account''s status';
  end if;

  if p_new_status not in ('active', 'deactivated') then
    raise exception 'Status must be set to active or deactivated through this operation';
  end if;

  if p_reason is null or length(trim(p_reason)) = 0 then
    raise exception 'A reason is required';
  end if;

  -- Matches the app-layer max (setAccountStatusSchema in lib/actions/account-status.ts).
  if length(p_reason) > 500 then
    raise exception 'Reason is too long (500 characters max)';
  end if;

  if p_user_id = auth.uid() then
    raise exception 'You can''t change your own account status — ask another System Administrator to do it';
  end if;

  perform pg_advisory_xact_lock(hashtext('profiles:set_account_status'));

  select account_status into v_current_status from profiles where id = p_user_id;
  if v_current_status is null then
    raise exception 'This account no longer exists';
  end if;

  -- Only ever reachable when the target isn't the caller (guarded above). The last active System Administrator, the only CEO / CTO approver of a company's
  -- project budgets and the only CEO / CTO of a company are never deactivated: the lock above serialises two deactivations, so the second sees the first.
  if p_new_status = 'deactivated' then
    v_blockers := account_deactivation_blockers(p_user_id);
    if coalesce(array_length(v_blockers, 1), 0) > 0 then
      raise exception '%', v_blockers[1];
    end if;
  end if;

  update profiles
  set account_status = p_new_status,
      is_active = (p_new_status = 'active'),
      status_reason = p_reason,
      status_changed_by = auth.uid(),
      status_changed_at = now()
  where id = p_user_id;
end;
$$;

grant execute on function set_account_status(uuid, account_status, text) to authenticated;

-- ---------------------------------------------------------------------------------------------------------------------------------------------
-- A person cannot change their own is_active (it now gates access)
-- ---------------------------------------------------------------------------------------------------------------------------------------------
create or replace function guard_profiles_self_update()
returns trigger
language plpgsql
as $$
begin
  if auth.uid() is null or has_role('sys_admin') then
    return new;
  end if;

  if new.account_status is distinct from old.account_status
     and not (old.account_status = 'invited' and new.account_status = 'active') then
    raise exception 'account_status can only be changed by a System Administrator';
  end if;

  if new.email is distinct from old.email
    or new.is_active is distinct from old.is_active
    or new.status_reason is distinct from old.status_reason
    or new.status_changed_by is distinct from old.status_changed_by
    or new.status_changed_at is distinct from old.status_changed_at
  then
    raise exception 'Only full_name and locale can be self-updated — ask a System Administrator to change anything else.';
  end if;

  return new;
end;
$$;
-- ---------------------------------------------------------------------------------------------------------------------------------------------
-- Routing and role holders skip inactive people (new requests; approvals already pending are not touched)
-- ---------------------------------------------------------------------------------------------------------------------------------------------
create or replace function resolve_approver(p_approver_type text, p_employee_id uuid)
returns uuid
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_company_id uuid;
  v_manager_id uuid;
  v_requester_user_id uuid;
  v_grandmanager_id uuid;
  v_result uuid;
begin
  select company_id, manager_id, user_id into v_company_id, v_manager_id, v_requester_user_id
  from employees where id = p_employee_id;

  -- employment_status <> 'terminated' (not e.g. 'active' only) — a
  -- terminated employee should never remain resolvable as an approver of
  -- record indefinitely (nothing else in the schema cascades a
  -- termination into reassigning their reports or revoking their roles),
  -- but someone merely on_leave/suspended is still a legitimate approver.
  if p_approver_type = 'direct_manager' then
    if v_manager_id is null then
      -- Top of the org chart — exactly the CEO/CTO's own situation, since
      -- nothing ever assigns them a manager_id. Returning null here used to
      -- mean create_initial_approval()/decide_leave_approval() both treat
      -- this as "no approver could be resolved" and hard-block the
      -- submission outright. There is no manager requirement for a
      -- C-level exec ("there is no need of manager for them, approval
      -- wise, anyone can approve as C-Level executives"), so fall back to
      -- any OTHER active ceo/cto holder in the same company instead of
      -- leaving them permanently unable to submit their own leave/
      -- reimbursement/etc. The self-approval check in
      -- create_initial_approval()/decide_leave_approval() still applies
      -- normally if this ever resolved back to the requester themselves.
      select ur.user_id into v_result
      from user_roles ur
      where ur.role in ('ceo', 'cto')
        and ur.revoked_at is null
        and (ur.company_id is null or ur.company_id = v_company_id)
        and ur.user_id <> v_requester_user_id
        and not exists (
          select 1 from employees e2
          where e2.user_id = ur.user_id and (e2.employment_status = 'terminated' or e2.deleted_at is not null)
        )
        and user_is_active(ur.user_id)
      order by ur.granted_at asc
      limit 1;
    else
      select user_id into v_result from employees
      where id = v_manager_id and employment_status <> 'terminated' and deleted_at is null and user_is_active(user_id);
    end if;
  elsif p_approver_type = 'manager_of_manager' then
    select manager_id into v_grandmanager_id from employees where id = v_manager_id;
    if v_manager_id is null or v_grandmanager_id is null then
      -- Same top-of-org-chart dead end as direct_manager above: either this
      -- employee has no manager at all, or their manager has no manager of
      -- their own (e.g. reports straight to the CEO/CTO) — either way
      -- there's no "manager of manager" to resolve, so fall back to any
      -- other active ceo/cto holder for the same reason given above.
      select ur.user_id into v_result
      from user_roles ur
      where ur.role in ('ceo', 'cto')
        and ur.revoked_at is null
        and (ur.company_id is null or ur.company_id = v_company_id)
        and ur.user_id <> v_requester_user_id
        and not exists (
          select 1 from employees e2
          where e2.user_id = ur.user_id and (e2.employment_status = 'terminated' or e2.deleted_at is not null)
        )
        and user_is_active(ur.user_id)
      order by ur.granted_at asc
      limit 1;
    else
      select user_id into v_result from employees
      where id = v_grandmanager_id and employment_status <> 'terminated' and deleted_at is null and user_is_active(user_id);
    end if;
  elsif p_approver_type like 'role:%' then
    -- 'role:ceo' is treated as "any C-level exec" — ceo and cto are equal
    -- peers for approval-routing purposes (per the CTO rollout: "anyone
    -- can approve as C-Level executives"), so a workflow step configured
    -- as role:ceo is satisfied by whichever of them is available. Every
    -- other role:% value (role:hr_admin, role:finance, ...) keeps its
    -- exact single-role match, unchanged.
    select ur.user_id into v_result
    from user_roles ur
    where (
        case when p_approver_type = 'role:ceo' then ur.role in ('ceo', 'cto')
        else ur.role = replace(p_approver_type, 'role:', '')::app_role end
      )
      and ur.revoked_at is null
      and (ur.company_id is null or ur.company_id = v_company_id)
      and not exists (
        select 1 from employees e2
        where e2.user_id = ur.user_id and (e2.employment_status = 'terminated' or e2.deleted_at is not null)
      )
      and user_is_active(ur.user_id)
    order by ur.granted_at asc
    limit 1;
  end if;

  return v_result;
end;
$$;

create or replace function resolve_approver_for_company(p_approver_type text, p_company_id uuid)
returns uuid
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_result uuid;
begin
  if p_approver_type like 'role:%' then
    select ur.user_id into v_result
    from user_roles ur
    where (
        case when p_approver_type = 'role:ceo' then ur.role in ('ceo', 'cto')
        else ur.role = replace(p_approver_type, 'role:', '')::app_role end
      )
      and ur.revoked_at is null
      and (ur.company_id is null or ur.company_id = p_company_id)
      and not exists (
        select 1 from employees e2
        where e2.user_id = ur.user_id and (e2.employment_status = 'terminated' or e2.deleted_at is not null)
      )
      and user_is_active(ur.user_id)
    order by ur.granted_at asc
    limit 1;
  end if;
  return v_result;
end;
$$;

create or replace function resolve_role_holders(p_role app_role, p_company_id uuid)
returns setof uuid
language sql
stable
security definer
set search_path = public
as $$
  select user_id
  from user_roles
  where role = p_role
    and revoked_at is null
    and (company_id is null or company_id = p_company_id)
    and user_is_active(user_id)
  order by granted_at asc;
$$;

-- ---------------------------------------------------------------------------------------------------------------------------------------------
-- Recovery Leave routing and the role-queue check of create_initial_approval
-- ---------------------------------------------------------------------------------------------------------------------------------------------
create or replace function recovery_eligible_approver_exists(p_company_id uuid, p_roles app_role[], p_exclude_user uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (
    select 1 from user_roles ur
    where ur.role = any (p_roles)
      and ur.revoked_at is null
      and (ur.company_id is null or ur.company_id = p_company_id)
      and ur.country_code is null
      and ur.user_id is distinct from p_exclude_user
      and not exists (
        select 1 from employees e2
        where e2.user_id = ur.user_id and (e2.employment_status = 'terminated' or e2.deleted_at is not null)
      )
      and user_is_active(ur.user_id)
  );
$$;

create or replace function create_initial_approval(p_entity_type approvable_entity, p_entity_id uuid)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_company_id uuid;
  v_employee_id uuid;
  v_workflow_id uuid;
  v_approver_type text;
  v_approver_id uuid;
  v_approval_id uuid;
  v_self_check_user_id uuid;
  v_applicant_route text;
  v_project_lead_employee_id uuid;
begin
  -- Every recovery_credit row is now created under a real logged-in user
  -- session — the employee's own session for a self-clock candidate (see
  -- attendance_segments' doc comment), or the acting HR Admin/manager's
  -- session for the legacy manual/overnight paths — so is_entity_owner()'s
  -- created_by = auth.uid() check applies uniformly, with no service-role,
  -- no-session exception needed. (is_entity_owner()'s own recovery_credit
  -- branch ALSO accepts any HR Admin of the request's company — needed for
  -- resolve_recovery_credit_project_lead() below, which routes a self-clock
  -- request an EMPLOYEE created after HR supplies its missing lead.)
  if not is_entity_owner(p_entity_type, p_entity_id) then
    raise exception 'You do not own this % (or it does not exist)', p_entity_type;
  end if;

  -- Idempotent under concurrent double-submission — moved up front so it
  -- covers the new self-clock route-driven branch below the same way as
  -- the legacy workflow-driven path further down (see that path's own doc
  -- comment on reimbursement claims/timesheets/payroll runs).
  select id into v_approval_id from approvals
  where entity_type = p_entity_type and entity_id = p_entity_id and step_order = 1;
  if v_approval_id is not null then
    return v_approval_id;
  end if;

  if p_entity_type = 'leave_request' then
    select e.company_id, r.employee_id into v_company_id, v_employee_id
    from leave_requests r join employees e on e.id = r.employee_id where r.id = p_entity_id;
  elsif p_entity_type = 'reimbursement_claim' then
    select e.company_id, c.employee_id into v_company_id, v_employee_id
    from reimbursement_claims c join employees e on e.id = c.employee_id where c.id = p_entity_id;
  elsif p_entity_type = 'timesheet' then
    select e.company_id, t.employee_id into v_company_id, v_employee_id
    from timesheets t join employees e on e.id = t.employee_id where t.id = p_entity_id;
  elsif p_entity_type = 'generated_letter' then
    select e.company_id, l.employee_id into v_company_id, v_employee_id
    from generated_letters l join employees e on e.id = l.employee_id where l.id = p_entity_id;
  elsif p_entity_type = 'payroll_export_run' then
    select company_id into v_company_id from payroll_export_runs where id = p_entity_id;
  elsif p_entity_type = 'recovery_credit' then
    select e.company_id, r.employee_id, r.applicant_route, r.project_lead_employee_id
    into v_company_id, v_employee_id, v_applicant_route, v_project_lead_employee_id
    from recovery_credit_requests r join employees e on e.id = r.employee_id where r.id = p_entity_id;
  else
    raise exception 'Unsupported entity type: %', p_entity_type;
  end if;

  -- NEW self-clock 4-tier routing (recovery_credit_requests.applicant_route
  -- is set — see that column's own doc comment) — bypasses
  -- approval_workflows/approval_workflow_steps entirely: the four routes
  -- have different total step counts and different step_order meanings,
  -- which doesn't fit the single company-wide workflow the generic engine
  -- below otherwise assumes. The LEGACY attendance_record_id-anchored
  -- recovery_credit family (applicant_route null) falls through to that
  -- same generic engine completely unchanged.
  if p_entity_type = 'recovery_credit' and v_applicant_route is not null then
    select user_id into v_self_check_user_id from employees where id = v_employee_id;

    if v_applicant_route = 'employee_lead_then_hr' then
      select user_id into v_approver_id from employees where id = v_project_lead_employee_id;
      if v_approver_id is null then
        raise exception 'The named project lead has no HR Engine account to approve with. Contact HR Admin.';
      end if;
      -- Defense in depth — resolve_recovery_credit_route() only ever
      -- returns this route when the lead is NOT the applicant themselves,
      -- so this should be unreachable in practice.
      if v_approver_id = v_self_check_user_id then
        raise exception 'The resolved project lead is you — this should have routed to self_led_hr_direct instead. Contact HR Admin.';
      end if;
      begin
        insert into approvals (entity_type, entity_id, step_order, approver_id, decision)
        values (p_entity_type, p_entity_id, 1, v_approver_id, 'pending')
        returning id into v_approval_id;
      exception when unique_violation then
        select id into v_approval_id from approvals where entity_type = p_entity_type and entity_id = p_entity_id and step_order = 1;
      end;
    else
      -- Single-step queue routes: manager_hr_direct/self_led_hr_direct go
      -- to any current hr_admin; hr_admin_ceo_cto_queue goes to either a
      -- ceo or a cto (approvals.queue_roles' own doc comment — the
      -- existing row-lock-plus-pending-check every decision already takes
      -- is what makes "whoever decides first wins" hold here too).
      begin
        insert into approvals (entity_type, entity_id, step_order, queue_roles, decision)
        values (
          p_entity_type, p_entity_id, 1,
          case v_applicant_route when 'hr_admin_ceo_cto_queue' then array['ceo', 'cto']::app_role[] else array['hr_admin']::app_role[] end,
          'pending'
        )
        returning id into v_approval_id;
      exception when unique_violation then
        select id into v_approval_id from approvals where entity_type = p_entity_type and entity_id = p_entity_id and step_order = 1;
      end;
    end if;

    return v_approval_id;
  end if;

  select id into v_workflow_id from approval_workflows
  where company_id = v_company_id and entity_type = p_entity_type and is_active = true
  order by created_at asc
  limit 1;
  if v_workflow_id is null then
    raise exception 'No approval workflow is configured for your company. Contact HR Admin.';
  end if;

  select approver_type into v_approver_type
  from approval_workflow_steps where workflow_id = v_workflow_id and step_order = 1;
  if v_approver_type is null then
    raise exception 'This workflow has no first step configured. Contact HR Admin.';
  end if;

  -- CEO/CTO applicant (docs/08-decisions-log.md): there is nobody above them,
  -- so their LEAVE needs no approver and is approved on the spot (through the
  -- same decide_leave_approval() finalisation every approval uses, so the
  -- balance/ledger work is identical), and their REIMBURSEMENT CLAIMS go
  -- straight to Finance instead of to a manager. Everything else (timesheets,
  -- letters, payroll runs, every other applicant) is unchanged. Leave and
  -- claims are always submitted by the requester's own session, which is what
  -- lets decide_leave_approval() accept the system's decision below.
  if p_entity_type in ('leave_request', 'reimbursement_claim') and v_employee_id is not null then
    select user_id into v_self_check_user_id from employees where id = v_employee_id;
    if is_c_level(v_self_check_user_id, v_company_id) then
      if p_entity_type = 'leave_request' then
        begin
          insert into approvals (entity_type, entity_id, workflow_id, step_order, approver_id, decision)
          values (p_entity_type, p_entity_id, v_workflow_id, 1, v_self_check_user_id, 'pending')
          returning id into v_approval_id;
        exception when unique_violation then
          select id into v_approval_id from approvals
          where entity_type = p_entity_type and entity_id = p_entity_id and step_order = 1;
          return v_approval_id;
        end;
        perform decide_leave_approval(
          v_approval_id, 'approved',
          'Approved automatically: a CEO or CTO''s leave needs no approver.'
        );
        return v_approval_id;
      else
        v_approver_type := 'role:finance';
      end if;
    end if;
  end if;

  if v_approver_type like 'role_queue:%' then
    -- Company-scoped role queue (currently only recovery_credit's single
    -- HR step) — no single resolved approver_id; ANY current holder of
    -- this role in the company may later decide it (see
    -- decide_leave_approval()'s own null-approver_id authorization branch).
    -- Still hard-stops here if literally no one currently holds the role,
    -- for the same "never create an unroutable approval" reason every
    -- other branch below does.
    if not exists (
      select 1 from user_roles ur
      where ur.role = replace(v_approver_type, 'role_queue:', '')::app_role
        and ur.revoked_at is null
        and (ur.company_id is null or ur.company_id = v_company_id)
        and not exists (
          select 1 from employees e2
          where e2.user_id = ur.user_id and (e2.employment_status = 'terminated' or e2.deleted_at is not null)
        )
        and user_is_active(ur.user_id)
    ) then
      raise exception 'No approver could be resolved (no one currently holds the "%" role in your company). Contact Sys Admin.', replace(v_approver_type, 'role_queue:', '');
    end if;
    v_approver_id := null;
  else
    if p_entity_type = 'payroll_export_run' then
      v_approver_id := resolve_approver_for_company(v_approver_type, v_company_id);
    else
      v_approver_id := resolve_approver(v_approver_type, v_employee_id);
    end if;
    if v_approver_id is null then
      raise exception 'No approver could be resolved (e.g. no manager assigned, or no one holds the required role). Contact HR Admin.';
    end if;

    -- Self-approval prevention for step 1 — decide_leave_approval() already
    -- refuses to route any LATER step back to the requester; this is the
    -- same check for the first step, which that function never sees.
    -- Compares against the ENTITY's own beneficiary, not always the
    -- caller: every other entity type is self-submitted (the caller IS the
    -- requester, so auth.uid() is correct), but recovery_credit is
    -- manager/HR-initiated ON BEHALF OF the employee — the direct manager
    -- routinely is both the one recording eligibility AND the resolved
    -- step-1 approver for their own report, which is never "self-approval"
    -- (they aren't approving their OWN leave). Only block if the resolved
    -- approver equals the beneficiary. A role_queue step has no single
    -- resolved approver to compare here at all — its own self-decision
    -- block instead happens at decision time, in decide_leave_approval().
    if p_entity_type = 'recovery_credit' then
      select user_id into v_self_check_user_id from employees where id = v_employee_id;
    else
      v_self_check_user_id := auth.uid();
    end if;
    if v_approver_id = v_self_check_user_id then
      raise exception 'The resolved approver for this workflow''s first step (%) is you — you can''t approve your own request. Contact HR Admin to assign a different approver.', v_approver_type;
    end if;
  end if;

  -- Idempotent under concurrent double-submission: reimbursement claims,
  -- timesheets, and payroll runs submit against an EXISTING row (an
  -- UPDATE then this call), so two racing calls can both pass every check
  -- above before either has inserted. Returning the existing step-1
  -- approval instead of raising or duplicating means the "loser" of the
  -- race gets back the same approval the "winner" created, rather than
  -- its caller (e.g. submitPayrollRun()) treating this as a routing
  -- failure and reverting the entity's status out from under a real,
  -- already-pending approval. The unique index above is the backstop for
  -- the rare case where both SELECTs below race past each other too.
  select id into v_approval_id from approvals
  where entity_type = p_entity_type and entity_id = p_entity_id and step_order = 1;
  if v_approval_id is not null then
    return v_approval_id;
  end if;

  begin
    insert into approvals (entity_type, entity_id, workflow_id, step_order, approver_id, decision)
    values (p_entity_type, p_entity_id, v_workflow_id, 1, v_approver_id, 'pending')
    returning id into v_approval_id;
  exception when unique_violation then
    select id into v_approval_id from approvals
    where entity_type = p_entity_type and entity_id = p_entity_id and step_order = 1;
  end;

  return v_approval_id;
end;
$$;

create or replace function recovery_route_request(p_request_id uuid)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  r recovery_credit_requests%rowtype;
  v_company uuid;
  v_user uuid;
  v_lead_user uuid;
  v_roles app_role[];
  v_approval_id uuid;
begin
  select * into r from recovery_credit_requests where id = p_request_id for update;
  if not found then raise exception 'Recovery credit request not found.'; end if;
  select e.company_id, e.user_id into v_company, v_user from employees e where e.id = r.employee_id;

  select id into v_approval_id from approvals where entity_type = 'recovery_credit' and entity_id = p_request_id and step_order = 1;
  if v_approval_id is not null then return v_approval_id; end if;
  -- A CEO/CTO's credit needs no approver. When nothing blocks it (the window is
  -- closed and verified, the amount is current) it is approved right here, by the
  -- system, through the same decide_leave_approval() finalisation as any approval.
  -- It only runs for the background processor (no signed-in user) or the CEO/CTO's
  -- own session, so a correction an HR Admin makes after approval creates a
  -- request that goes to the HR queue for a human to approve, never auto-approved.
  -- Anything recovery_request_blocker() reports (HR verification pending, a
  -- reduction that needs acknowledging, a stale amount) also falls through to the
  -- normal single-step HR queue below.
  if is_c_level(v_user, v_company)
     and (auth.uid() is null or auth.uid() = v_user)
     and recovery_request_blocker(p_request_id) is null then
    begin
      insert into approvals (entity_type, entity_id, step_order, approver_id, decision)
      values ('recovery_credit', p_request_id, 1, v_user, 'pending')
      returning id into v_approval_id;
    exception when unique_violation then
      select id into v_approval_id from approvals
      where entity_type = 'recovery_credit' and entity_id = p_request_id and step_order = 1;
      return v_approval_id;
    end;
    perform decide_leave_approval(
      v_approval_id, 'approved',
      'Approved automatically: a CEO or CTO''s Recovery Leave needs no approver.'
    );
    update recovery_credit_requests set routing_issue = null where id = p_request_id and routing_issue is not null;
    return v_approval_id;
  end if;

  if r.applicant_route is null then return null; end if;

  if r.applicant_route = 'employee_lead_then_hr' then
    select e.user_id into v_lead_user from employees e
    where e.id = r.project_lead_employee_id and e.employment_status <> 'terminated' and e.deleted_at is null and user_is_active(e.user_id);
    if v_lead_user is null then
      update recovery_credit_requests set routing_issue = 'The named project lead has no active HR Engine account to approve with. HR must assign another lead.' where id = p_request_id;
      return null;
    end if;
    if v_lead_user = v_user then
      update recovery_credit_requests set routing_issue = 'The resolved project lead is the applicant. HR must review this request.' where id = p_request_id;
      return null;
    end if;
    if not recovery_eligible_approver_exists(v_company, array['hr_admin']::app_role[], v_user) then
      update recovery_credit_requests set routing_issue = 'No HR Admin is currently available to take the second approval step.' where id = p_request_id;
      return null;
    end if;
    insert into approvals (entity_type, entity_id, step_order, approver_id, decision)
    values ('recovery_credit', p_request_id, 1, v_lead_user, 'pending')
    on conflict (entity_type, entity_id, step_order) do nothing
    returning id into v_approval_id;
  else
    v_roles := case r.applicant_route when 'hr_admin_ceo_cto_queue' then array['ceo', 'cto']::app_role[] else array['hr_admin']::app_role[] end;
    if not recovery_eligible_approver_exists(v_company, v_roles, v_user) then
      update recovery_credit_requests
      set routing_issue = 'No eligible approver currently holds the ' || array_to_string(v_roles, ' or ') || ' role for this company.'
      where id = p_request_id;
      return null;
    end if;
    insert into approvals (entity_type, entity_id, step_order, queue_roles, decision)
    values ('recovery_credit', p_request_id, 1, v_roles, 'pending')
    on conflict (entity_type, entity_id, step_order) do nothing
    returning id into v_approval_id;
  end if;

  update recovery_credit_requests set routing_issue = null where id = p_request_id and routing_issue is not null;
  if v_approval_id is null then
    select id into v_approval_id from approvals where entity_type = 'recovery_credit' and entity_id = p_request_id and step_order = 1;
  end if;
  return v_approval_id;
end;
$$;
-- ==== END MIGRATION 20261216000300_account_deactivation_inactive_people.sql ====

-- ==== BEGIN MIGRATION 20261216000400_profiles_status_columns_restricted.sql (3499 bytes, sha256 1c3b6852c040582c48c880ae9f7d1c1ed7d186b27a1ebfcb3fe0f2317153eb93) ====
-- A13 / D-11. The deactivation reason is no longer readable by every signed-in user. ADDITIVE: changes SELECT privileges on one table (profiles) and adds one function;
-- no data changes, no policy change, nothing is lost.
--
-- WHY (reproduced on a local copy before the fix: packages/rls-tests/test/profiles_status_columns.rls.test.ts). profiles_select lets every signed-in user read every
-- profile row, and migration 20261104000000 added status_reason (free text a System Administrator types when deactivating an account: it can describe misconduct),
-- status_changed_by and status_changed_at to the same table without narrowing the read. Any employee could read them through the API.
--
-- WHAT.
--   * SELECT on profiles is limited to the directory columns people pickers and approver / manager names need: id, email, full_name, locale, is_active, account_status,
--     created_at, updated_at. status_reason, status_changed_by and status_changed_at can no longer be read directly by anyone signed in (including a System Administrator:
--     they read them through the function below, which checks the role inside). Anonymous visitors lose the table privilege altogether (row-level security already
--     answered them nothing; nothing in the application reads profiles without signing in).
--   * account_status_details(user_id) returns those three values (and the name of the person who made the change) to a System Administrator only.
--
-- WHAT DOES NOT CHANGE. Row visibility (profiles_select and the update policies), names, e-mails and the status itself stay readable for everyone signed in, a person
-- still updates their own name and locale and still completes the first sign-in activation, set_account_status() still records the reason, and the audit trail is
-- unchanged. INSERT, UPDATE and DELETE privileges are untouched. SECURITY DEFINER functions are unaffected.
--
-- TWO THINGS TO KNOW. (1) `select *` on profiles is now refused for signed-in users (naming the columns works); nothing in the application does that. (2) A column
-- added to profiles later is not readable by signed-in users until it is granted explicitly: that is deliberate (a new column starts private).
-- ROLLBACK: supabase/manual-sql/profstat_90_rollback.sql (grants the whole table to signed-in users again: this re-opens the exposure).

revoke select on table profiles from anon, authenticated;
grant select (id, email, full_name, locale, is_active, account_status, created_at, updated_at) on table profiles to authenticated;

create or replace function account_status_details(p_user_id uuid)
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  p profiles%rowtype;
begin
  if auth.uid() is null or not has_role('sys_admin') then
    raise exception 'Only a System Administrator can read the reason an account was deactivated' using errcode = '42501';
  end if;
  select * into p from profiles where id = p_user_id;
  if not found then return null; end if;
  return jsonb_build_object(
    'account_status', p.account_status,
    'status_reason', p.status_reason,
    'status_changed_at', p.status_changed_at,
    'status_changed_by', p.status_changed_by,
    'status_changed_by_name', (select coalesce(nullif(btrim(c.full_name), ''), c.email) from profiles c where c.id = p.status_changed_by)
  );
end;
$$;

revoke all on function account_status_details(uuid) from public, anon;
grant execute on function account_status_details(uuid) to authenticated;
-- ==== END MIGRATION 20261216000400_profiles_status_columns_restricted.sql ====

-- ==== BEGIN MIGRATION 20261216000500_attendance_lead_candidates.sql (2192 bytes, sha256 b0cc0d5d3303e4b569d4e77284bfb341c003abbfc8be99bb2441aa1e587be07e) ====
-- A14 / D-13. The "Project lead" picker on the attendance clock lists the people an ordinary employee can choose. ADDITIVE: one new function; no table, policy or
-- privilege change, no data change.
--
-- WHY (reproduced on a local copy before the fix: packages/rls-tests/test/clock_lead_candidates.rls.test.ts). The picker was filled by reading `employees` through the
-- person's own session. employees_select lets an ordinary employee read only their own row (a manager also reads their reports), so the list held only the person
-- themself, while "Site work" cannot be started without naming a lead, and choosing oneself routes the Recovery Leave request to HR direct instead of through the lead.
--
-- WHAT. attendance_lead_candidates() returns ONLY an id and a display name for the active people (employment status active, not deleted) of the CALLER's own company, the
-- same people validate_attendance_segment_inputs() accepts as a lead (same company, currently active). The clock and the form that supplies a missing lead read it.
-- It adds no read of the employees table: the employee still cannot read any other employee row or column.
--
-- WHAT DOES NOT CHANGE. validate_attendance_segment_inputs() still rejects a lead of another company or a person who is not active; attendance rules, Recovery Leave
-- routing and every calculation; employees_select. Callable by signed-in users only.
-- ROLLBACK: supabase/manual-sql/leadpick_90_rollback.sql (drops the function: the picker goes back to the person themself).

create or replace function attendance_lead_candidates()
returns table(employee_id uuid, display_name text)
language sql stable security definer
set search_path = public
as $$
  select e.id,
         coalesce(nullif(btrim(concat_ws(' ', e.first_name, e.last_name)), ''), 'Unnamed colleague')
  from employees me
  join employees e on e.company_id = me.company_id
  where me.id = current_employee_id()
    and e.employment_status = 'active'
    and e.deleted_at is null
  order by e.first_name, e.last_name, e.id;
$$;

revoke all on function attendance_lead_candidates() from public, anon;
grant execute on function attendance_lead_candidates() to authenticated;
-- ==== END MIGRATION 20261216000500_attendance_lead_candidates.sql ====

-- ==== BEGIN MIGRATION 20261216000600_recovery_decider_inbox.sql (4466 bytes, sha256 ea66808f22a255bd7549014752ea38860b76e6927c25d86d58e01c1db17b265f) ====
-- A15 / D-14. The Approvals page can show a Recovery Leave card to the people who actually decide it. ADDITIVE: one new function; no table, policy or privilege change,
-- no data change, and no change to routing, the decision, or any calculation.
--
-- WHY (reproduced on a local copy before the fix: packages/rls-tests/test/recovery_decider_card.rls.test.ts).
--   (1) A project lead who decides step 1 saw the applicant's name as "—": the page read it from `employees`, which a lead who is not the person's manager cannot read.
--   (2) A CEO / CTO deciding an HR Admin's request on the shared queue got no card at all, for two reasons that stack: the queue approval row itself is invisible to them
--       (approvals_select looks the request up under the caller's own row-level security, and recovery_credit_requests_select has no CEO / CTO branch), and so is the
--       request row the card is built from. The page said "Nothing waiting on you" although the approval exists and the database lets them decide.
--
-- WHAT. recovery_decider_inbox(ids) returns, for each pending approval that the CALLER is authorised to decide RIGHT NOW (a step assigned to them, or a pending queue step
-- whose role (HR Admin, or the CEO / CTO queue roles) they hold in the APPLICANT's company), the approval's own fields (so the page can list it) and the minimum the card shows:
-- the applicant's name, company and country, and the request's own work date, event type, amount, route, work mode, project name, named lead, routing note and window link.
-- With no list it returns all of them. The applicant is never offered their own request, a decision already made is not offered again, and a CEO / CTO / HR Admin of another
-- company gets nothing. Not returned: checked-with notes, correction reasons, segment ids, attendance records, anything outside the card.
--
-- WHAT DOES NOT CHANGE. approvals_select and recovery_credit_requests_select (nobody can read more rows of either table than before), who may decide, routing, approvals,
-- ledgers, the window evidence the page already reads under its own policies. Callable by signed-in users only (a caller who decides nothing gets an empty result).
-- ROLLBACK: supabase/manual-sql/reccard_90_rollback.sql (drops the function: the card goes back to what the page can read itself).

create or replace function recovery_decider_inbox(p_request_ids uuid[] default null)
returns table(
  approval_id uuid,
  step_order int,
  workflow_id uuid,
  approver_id uuid,
  queue_roles app_role[],
  approval_created_at timestamptz,
  id uuid,
  employee_id uuid,
  employee_name text,
  company_id uuid,
  country_code text,
  work_date date,
  event_type text,
  proposed_days numeric,
  attendance_record_id uuid,
  corrected_at timestamptz,
  work_mode text,
  project_name text,
  project_lead_employee_id uuid,
  applicant_route text,
  needs_policy_review boolean,
  routing_issue text,
  recovery_window_id uuid,
  consumption_ack_at timestamptz
)
language sql stable security definer
set search_path = public
as $$
  select a.id, a.step_order, a.workflow_id, a.approver_id, a.queue_roles, a.created_at,
         r.id, r.employee_id,
         coalesce(nullif(btrim(concat_ws(' ', e.first_name, e.last_name)), ''), 'Unnamed employee'),
         e.company_id, e.country_code,
         r.work_date, r.event_type::text, r.proposed_days, r.attendance_record_id, r.corrected_at, r.work_mode::text, r.project_name,
         r.project_lead_employee_id, r.applicant_route::text, r.needs_policy_review, r.routing_issue, r.recovery_window_id, r.consumption_ack_at
  from approvals a
  join recovery_credit_requests r on r.id = a.entity_id
  join employees e on e.id = r.employee_id
  where auth.uid() is not null
    and a.entity_type = 'recovery_credit' and a.decision = 'pending'
    and (p_request_ids is null or r.id = any (p_request_ids))
    and e.user_id is distinct from auth.uid()
    and (
      a.approver_id = auth.uid()
      or (
        a.approver_id is null
        and (
          (a.queue_roles is null and has_role('hr_admin', e.company_id))   -- the earlier single HR queue step
          or (a.queue_roles is not null and exists (select 1 from unnest(a.queue_roles) qr where has_role(qr, e.company_id)))
        )
      )
    )
  order by a.created_at, a.id;
$$;

revoke all on function recovery_decider_inbox(uuid[]) from public, anon;
grant execute on function recovery_decider_inbox(uuid[]) to authenticated;
-- ==== END MIGRATION 20261216000600_recovery_decider_inbox.sql ====

-- ==== BEGIN MIGRATION 20261216000700_policy_status_role_check.sql (3573 bytes, sha256 a129d82c9ac4a8482026531ed81cdbb4a768c01f48dee19346c7d65258d1c24e) ====
-- A16 / D-22. preflight_phase2b_v2_policy_status() answers only the people who may read those drafts. ADDITIVE: replaces one function in place (create or replace) and
-- changes who may CALL it; no table, policy or data change.
--
-- WHY (reproduced on a local copy before the fix: packages/rls-tests/test/policy_status_role_check.rls.test.ts). The function is SECURITY DEFINER and had no role check and no
-- privilege restriction, and the Policies page called it for every viewer, so any signed-in employee (or, because execute was never revoked, any caller) could read the
-- status, effective date and key values of the seeded DRAFT leave, notice and probation policy versions, which policy_versions_select hides from them.
--
-- WHAT. A slot (country, policy type) is returned only to a person who may read that country's drafts: the same test as policy_versions_select and the draft-creation
-- function (has_role('hr_admin' | 'ceo' | 'cto', null, country): a grant not limited to one company). HR Admin sees the same rows as before; everyone else gets none.
-- Execute is also taken away from anonymous callers. The Policies page now calls it only for people who may draft.
--
-- WHAT DOES NOT CHANGE. The columns, the 12 slots, seed_phase2b_policy_drafts(), policy_versions' policies, every leave rule and calculation.
-- ROLLBACK: supabase/manual-sql/polstat_90_rollback.sql (re-installs the previous definition; the exposure returns).

create or replace function preflight_phase2b_v2_policy_status()
returns table(
  country_code text,
  policy_type text,
  version_no int,
  status text,
  effective_from date,
  critical_values jsonb,
  runtime_can_resolve_unambiguously boolean
)
language sql
stable
security definer
set search_path = public
as $$
  select
    cc.code,
    pt.policy_type,
    pv.version_no,
    coalesce(pv.status::text, 'not_created'),
    pv.effective_from,
    case
      when pv.id is null then null
      when pt.policy_type = 'leave_rules' then (
        select jsonb_object_agg(plt.leave_type_code, jsonb_build_object(
          'accrual_method', plt.accrual_method,
          'accrual_rate_per_period', plt.accrual_rate_per_period,
          'max_balance_days', plt.max_balance_days,
          'carryover_max_days', plt.carryover_max_days,
          'min_service_days_to_accrue', plt.min_service_days_to_accrue
        ))
        from policy_leave_types plt where plt.policy_version_id = pv.id
      )
      else pv.payload - 'phase2b_seed_marker'
    end,
    pv.id is not null and not exists (
      select 1 from policy_versions other
      where other.country_code = pv.country_code
        and other.policy_type = pv.policy_type
        and other.status = 'active'
        and other.id <> pv.id
        and other.effective_from <= coalesce(pv.effective_to, 'infinity'::date)
        and coalesce(other.effective_to, 'infinity'::date) >= pv.effective_from
    )
  from (values ('AE'), ('SA'), ('PL')) as cc(code)
  cross join (values ('leave_rules'), ('overtime_rules'), ('notice_period'), ('probation_rules')) as pt(policy_type)
  left join policy_versions pv
    on pv.country_code = cc.code
    and pv.policy_type::text = pt.policy_type
    and pv.payload ->> 'phase2b_seed_marker' = 'leave_policy_configuration'
  where has_role('hr_admin', null, cc.code) or has_role('ceo', null, cc.code) or has_role('cto', null, cc.code)
  order by cc.code, pt.policy_type;
$$;

revoke all on function preflight_phase2b_v2_policy_status() from public, anon;
grant execute on function preflight_phase2b_v2_policy_status() to authenticated;
-- ==== END MIGRATION 20261216000700_policy_status_role_check.sql ====

-- ==== BEGIN MIGRATION 20261216000800_letters_storage_issued_only.sql (2109 bytes, sha256 f8f339dbaf6ec948e574a71239873ad162ed6edb4aaeece9d3f5eb0934b2e7ed) ====
-- A17 / D-23. An employee reads the stored file of their own letter only once it is ISSUED. ADDITIVE: replaces one storage read policy (drop + create, same name, same
-- role, narrower for one branch); no table, no data, no other policy changes. Nothing already issued becomes unreadable by its owner.
--
-- WHY (reproduced on a local copy before the fix: packages/rls-tests/test/letters_pending_storage.rls.test.ts). The application renders the letter PDF and stores it BEFORE
-- the approval is routed, so a letter that needs CEO / CTO sign-off has a file while it is "pending approval". The letters_select policy let the owning employee read any
-- file under their own folder, whatever the letter's status, so the file was in the employee's hands before sign-off (and stayed there after a rejection or a void).
--
-- WHAT. The employee branch of letters_select now also requires a generated_letters row for that exact file with status = 'issued'. A file with no letter row is not
-- readable by the employee. The HR Admin branch is unchanged (HR reviews drafts before they are signed), and so are the CEO / CTO read policy (letters_select_ceo: the
-- executive needs the file to decide), uploads and deletes. The Letters page offers Download to an employee only for issued letters (interface change in the same change).
--
-- WHAT DOES NOT CHANGE. generated_letters' own policies (the employee still sees their letter row, so the page can say "pending approval"), approvals, templates.
-- ROLLBACK: supabase/manual-sql/letters_90_rollback.sql (re-creates the previous policy: the exposure returns).

drop policy if exists letters_select on storage.objects;
create policy letters_select on storage.objects for select
  using (
    bucket_id = 'letters'
    and (
      (
        (storage.foldername(name))[2]::uuid = current_employee_id()
        and exists (
          select 1 from generated_letters gl
          where gl.file_path = name and gl.employee_id = current_employee_id() and gl.status = 'issued'
        )
      )
      or has_role('hr_admin', (storage.foldername(name))[1]::uuid)
    )
  );
-- ==== END MIGRATION 20261216000800_letters_storage_issued_only.sql ====

-- ==== BEGIN MIGRATION 20261216000810_approval_routing_country_scope.sql (7991 bytes, sha256 715a1beb2b77fa0abf1f151a533c93dee9332c6a5f55799a4ab228abc7c99c67) ====
-- Approval routing honours the COUNTRY limit on a role grant. ADDITIVE: replaces two functions in place (create or replace); no table, column, policy, privilege or data change.
--
-- WHY (reproduced locally before the fix: packages/rls-tests/test/approval_routing_scope.rls.test.ts). resolve_approver() and resolve_approver_for_company() honoured the company
-- limit on a role grant but ignored its country limit, so a CEO (or any role holder) limited to ONE country was resolved as approver for every company that has no company-limited
-- holder, in every country.
--
-- THE RULE (existing, not new): user_roles are "optionally scoped to a company/country, e.g. HR Admin for Poland only" (docs/02-database-schema.md) and has_role() applies a grant
-- when its company is null or the company asked about AND its country is null or the country asked about. A grant with no country limit is unaffected.
--   * resolve_approver(type, employee): a grant limited to a country applies when it is the EMPLOYEE's country (employees.country_code). This covers 'role:*' and the managerless
--     CEO / CTO fallback of direct_manager / manager_of_manager.
--   * resolve_approver_for_company(type, company): a grant limited to a country applies when it is the COMPANY's country (companies.country_code).
--
-- WHAT DOES NOT CHANGE: grants with no country limit (company-only and global) resolve exactly as before; inactive, terminated and revoked holders are still skipped; the
-- 'role:ceo' = CEO or CTO rule, the ordering (oldest grant first) and the self-approval refusals; APPROVALS ALREADY PENDING keep their approver (nothing re-routes them: only
-- new requests use the corrected lookup); the shared-queue checks (has_role on the caller), resolve_role_holders (notification recipients) and every other function.
-- Rollback: supabase/manual-sql/apprscope_90_rollback.sql restores the previous bodies.

create or replace function resolve_approver(p_approver_type text, p_employee_id uuid)
returns uuid
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_company_id uuid;
  v_country text;
  v_manager_id uuid;
  v_requester_user_id uuid;
  v_grandmanager_id uuid;
  v_result uuid;
begin
  select company_id, country_code, manager_id, user_id into v_company_id, v_country, v_manager_id, v_requester_user_id
  from employees where id = p_employee_id;

  -- employment_status <> 'terminated' (not e.g. 'active' only) — a
  -- terminated employee should never remain resolvable as an approver of
  -- record indefinitely (nothing else in the schema cascades a
  -- termination into reassigning their reports or revoking their roles),
  -- but someone merely on_leave/suspended is still a legitimate approver.
  if p_approver_type = 'direct_manager' then
    if v_manager_id is null then
      -- Top of the org chart — exactly the CEO/CTO's own situation, since
      -- nothing ever assigns them a manager_id. Returning null here used to
      -- mean create_initial_approval()/decide_leave_approval() both treat
      -- this as "no approver could be resolved" and hard-block the
      -- submission outright. There is no manager requirement for a
      -- C-level exec ("there is no need of manager for them, approval
      -- wise, anyone can approve as C-Level executives"), so fall back to
      -- any OTHER active ceo/cto holder in the same company instead of
      -- leaving them permanently unable to submit their own leave/
      -- reimbursement/etc. The self-approval check in
      -- create_initial_approval()/decide_leave_approval() still applies
      -- normally if this ever resolved back to the requester themselves.
      select ur.user_id into v_result
      from user_roles ur
      where ur.role in ('ceo', 'cto')
        and ur.revoked_at is null
        and (ur.company_id is null or ur.company_id = v_company_id)
        and (ur.country_code is null or ur.country_code = v_country)
        and ur.user_id <> v_requester_user_id
        and not exists (
          select 1 from employees e2
          where e2.user_id = ur.user_id and (e2.employment_status = 'terminated' or e2.deleted_at is not null)
        )
        and user_is_active(ur.user_id)
      order by ur.granted_at asc
      limit 1;
    else
      select user_id into v_result from employees
      where id = v_manager_id and employment_status <> 'terminated' and deleted_at is null and user_is_active(user_id);
    end if;
  elsif p_approver_type = 'manager_of_manager' then
    select manager_id into v_grandmanager_id from employees where id = v_manager_id;
    if v_manager_id is null or v_grandmanager_id is null then
      -- Same top-of-org-chart dead end as direct_manager above: either this
      -- employee has no manager at all, or their manager has no manager of
      -- their own (e.g. reports straight to the CEO/CTO) — either way
      -- there's no "manager of manager" to resolve, so fall back to any
      -- other active ceo/cto holder for the same reason given above.
      select ur.user_id into v_result
      from user_roles ur
      where ur.role in ('ceo', 'cto')
        and ur.revoked_at is null
        and (ur.company_id is null or ur.company_id = v_company_id)
        and (ur.country_code is null or ur.country_code = v_country)
        and ur.user_id <> v_requester_user_id
        and not exists (
          select 1 from employees e2
          where e2.user_id = ur.user_id and (e2.employment_status = 'terminated' or e2.deleted_at is not null)
        )
        and user_is_active(ur.user_id)
      order by ur.granted_at asc
      limit 1;
    else
      select user_id into v_result from employees
      where id = v_grandmanager_id and employment_status <> 'terminated' and deleted_at is null and user_is_active(user_id);
    end if;
  elsif p_approver_type like 'role:%' then
    -- 'role:ceo' is treated as "any C-level exec" — ceo and cto are equal
    -- peers for approval-routing purposes (per the CTO rollout: "anyone
    -- can approve as C-Level executives"), so a workflow step configured
    -- as role:ceo is satisfied by whichever of them is available. Every
    -- other role:% value (role:hr_admin, role:finance, ...) keeps its
    -- exact single-role match, unchanged.
    select ur.user_id into v_result
    from user_roles ur
    where (
        case when p_approver_type = 'role:ceo' then ur.role in ('ceo', 'cto')
        else ur.role = replace(p_approver_type, 'role:', '')::app_role end
      )
      and ur.revoked_at is null
      and (ur.company_id is null or ur.company_id = v_company_id)
        and (ur.country_code is null or ur.country_code = v_country)
      and not exists (
        select 1 from employees e2
        where e2.user_id = ur.user_id and (e2.employment_status = 'terminated' or e2.deleted_at is not null)
      )
      and user_is_active(ur.user_id)
    order by ur.granted_at asc
    limit 1;
  end if;

  return v_result;
end;
$$;

create or replace function resolve_approver_for_company(p_approver_type text, p_company_id uuid)
returns uuid
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_result uuid;
  v_country text;
begin
  if p_approver_type like 'role:%' then
    select country_code into v_country from companies where id = p_company_id;
    select ur.user_id into v_result
    from user_roles ur
    where (
        case when p_approver_type = 'role:ceo' then ur.role in ('ceo', 'cto')
        else ur.role = replace(p_approver_type, 'role:', '')::app_role end
      )
      and ur.revoked_at is null
      and (ur.company_id is null or ur.company_id = p_company_id)
      and (ur.country_code is null or ur.country_code = v_country)
      and not exists (
        select 1 from employees e2
        where e2.user_id = ur.user_id and (e2.employment_status = 'terminated' or e2.deleted_at is not null)
      )
      and user_is_active(ur.user_id)
    order by ur.granted_at asc
    limit 1;
  end if;
  return v_result;
end;
$$;

-- ==== END MIGRATION 20261216000810_approval_routing_country_scope.sql ====

-- ==== BEGIN MIGRATION 20261216000820_proj_scope_decision_context.sql (4344 bytes, sha256 5a2ac029bc1e0e73348a46e46dce2df5e6bb4b165e2e41f234ec0e75994d1c97) ====
-- Scope-change deciders can open the decision without belonging to the project (completion pass, section 3). ADDITIVE: adds two read-only functions; no table, column, policy, trigger
-- or privilege on anything existing changes, and no data changes.
--
-- WHY. proj_decide_scope_change() authorises exactly one thing: the capability approve_scope (or founder) in the project's company. Nothing there asks for project membership.
-- But a holder of approve_scope who is neither a founder nor a member of the project could not READ the proposal (row-level security needs founder or membership), so they could
-- neither be told about it nor see what they were asked to approve. Reproduced in packages/rls-tests/test/project_scope_decision_context.rls.test.ts.
--
-- WHAT. Two functions that return ONLY what the decision form needs, to the people the decision function already authorises, and nothing else:
--   * proj_scope_decisions_waiting()      the open proposals the caller may decide now: proposal id, project id, project reference and name, the proposal title, when it was proposed.
--   * proj_scope_decision_context(id)     one proposal for the decision page: the same fields, plus the proposed scope text, the stated effect on dates, who proposed it (display name)
--                                         and the proposal's status, and whether it can still be decided. An unknown proposal and a caller who may not decide it get no row.
-- WHAT THEY DO NOT RETURN: the project's current scope or any other project field, members, tasks, budget, handover, files, discussion, the cost effect of the proposal
-- (proj_scope_change_commercial stays behind view_commercial), the feedback that prompted it, or decision notes. They do not make anybody a member and read no project table for the caller.
-- Who may decide, the decision function and its checks are unchanged; so is who can read proj_scope_changes directly.
--
-- Founders and members who hold approve_scope get the same rows as before, plus open proposals on projects of their company they do not belong to (the decision the capability already
-- allows). The My Day row and the decision page use these functions; the notification for people who cannot open the project IS that row (the notice reader shows participants only).
-- Rollback: supabase/manual-sql/scopectx_90_rollback.sql drops both functions.

create or replace function proj_scope_decisions_waiting()
returns table (
  scope_change_id uuid,
  project_id uuid,
  project_reference text,
  project_name text,
  title text,
  proposed_at timestamptz
)
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform proj_require_user();
  return query
    select s.id, p.id, p.reference, p.name, s.title, s.proposed_at
      from proj_scope_changes s
      join proj_projects p on p.id = s.project_id
     where s.status = 'proposed'
       and p.status not in ('completed', 'archived')
       and proj_has_capability(p.company_id, 'approve_scope')
     order by s.proposed_at, s.id
     limit 200;
end;
$$;

create or replace function proj_scope_decision_context(p_scope_change_id uuid)
returns table (
  scope_change_id uuid,
  project_id uuid,
  project_reference text,
  project_name text,
  title text,
  proposed_scope text,
  effect_on_dates text,
  proposed_by_name text,
  proposed_at timestamptz,
  status text,
  can_decide boolean
)
language plpgsql stable security definer
set search_path = public
as $$
begin
  perform proj_require_user();
  return query
    select s.id, p.id, p.reference, p.name, s.title, s.proposed_scope, s.effect_on_dates,
           coalesce(nullif(btrim(pr.full_name), ''), 'the Project Manager'), s.proposed_at, s.status,
           (s.status = 'proposed' and p.status not in ('completed', 'archived'))
      from proj_scope_changes s
      join proj_projects p on p.id = s.project_id
      left join profiles pr on pr.id = s.proposed_by
     where s.id = p_scope_change_id
       and proj_has_capability(p.company_id, 'approve_scope');
end;
$$;

revoke all on function proj_scope_decisions_waiting() from public, anon;
revoke all on function proj_scope_decision_context(uuid) from public, anon;
grant execute on function proj_scope_decisions_waiting() to authenticated;
grant execute on function proj_scope_decision_context(uuid) to authenticated;
-- ==== END MIGRATION 20261216000820_proj_scope_decision_context.sql ====

-- ==== BEGIN MIGRATION 20261216000830_pbx_decisions_waiting_count.sql (2585 bytes, sha256 57c3d4292520479f49eb80ffe2eee8edb7fffae4645a98a6afda2118482c57d5) ====
-- A cheap "waiting for your decision" count for the Finance menu entry (completion pass, A8 leftover). ADDITIVE: adds one read-only function; no table, column, policy, trigger
-- or privilege on anything existing changes, and no data changes.
--
-- WHY. The Finance menu entry should show how many project budgets and final-expense sets wait for the person to decide, without making every page load run pbx_inbox(): that
-- function also computes settlement figures and blockers for every open budget of every company the person can read, which is far too much work for a menu badge.
--
-- WHAT. pbx_decisions_waiting_count() returns ONE number: the submitted budget versions plus the submitted final-expense sets that the caller may decide NOW. It uses exactly the
-- predicates pbx_inbox() uses for its two approval lists (company accessible to the caller, pbx_can_decide = the route's capability and not the person who prepared or submitted it,
-- and not on hold because nobody else could decide it), so the number equals the count of rows that pbx_inbox() marks i_can_decide and not on_hold. Not counted: settlement follow-ups
-- (receipts to confirm, ready to close); they stay in the inbox and on My Day. A person who cannot decide anything gets 0, a signed-out caller is refused.
-- The function returns a number only: no project, amount, name or company. Who may decide, every approval function and every other read are unchanged.
-- Rollback: supabase/manual-sql/pbxwait_90_rollback.sql drops the function.

create or replace function pbx_decisions_waiting_count()
returns integer
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_n integer;
begin
  perform pbx_require_user();
  select
    (select count(*) from pbx_budget_versions v
      where v.status = 'submitted' and v.company_id in (select pbx_accessible_company_ids())
        and pbx_can_decide(v.company_id, v.approval_route, v.created_by, v.submitted_by)
        and not pbx_approval_on_hold(v.company_id, v.approval_route, v.created_by, v.submitted_by))
    +
    (select count(*) from pbx_actual_submissions s
      where s.status = 'submitted' and s.company_id in (select pbx_accessible_company_ids())
        and pbx_can_decide(s.company_id, s.approval_route, s.created_by, s.submitted_by)
        and not pbx_approval_on_hold(s.company_id, s.approval_route, s.created_by, s.submitted_by))
    into v_n;
  return v_n;
end;
$$;

revoke all on function pbx_decisions_waiting_count() from public, anon;
grant execute on function pbx_decisions_waiting_count() to authenticated;
-- ==== END MIGRATION 20261216000830_pbx_decisions_waiting_count.sql ====

-- ==== BEGIN MIGRATION 20261216000900_proj_block_task_notifies_pm.sql (4384 bytes, sha256 9b312674b09bf6e7444657c9365fc595ab58da47d856a2f524fe84cdeec416e8) ====
-- A blocker that names someone other than the Project Manager also tells the Project Manager (completion pass, section 2). ADDITIVE: replaces one function in
-- place (create or replace); no table, column, policy or privilege changes, no data changes. Execute privileges are kept by create or replace.
--
-- WHY: proj_block_task told only the named unblocker. When that person was not the PM (a colleague, a team member), the PM, who is accountable for the project,
-- only learned of the blocker by opening the task.
--
-- RULE (unchanged part): the person named as able to unblock the task is told, or the Project Manager when no person is named (only an action is written).
-- NEW: when a person is named and is NOT the Project Manager, the Project Manager is ALSO told ('project_task_blocked' with fyi = true and the unblocker's
-- name, so the notice says who was asked and does not say the PM must act). One notice per person: nothing is sent twice to the same person (the named
-- person is the PM: one notice; proj_notify also deduplicates an unread notice with the same key), and the person who reports the blocker is never told about
-- their own action (proj_notify skips the caller), also when the reporter IS the PM. proj_notify's existing rules still decide who can be reached (an active
-- person who can open the project); nobody gains access to anything.
--
-- UNCHANGED: who may block (assignee, department head, PM), the required reason, the required unblock responsibility (a project member, or a written action), the
-- event record, and proj_unblock_task.

create or replace function proj_block_task(p_task_id uuid, p_reason text, p_unblock_owner uuid default null, p_unblock_action text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  t proj_tasks;
  v proj_projects;
  v_unblocker text;
begin
  perform proj_require_user();
  select * into t from proj_tasks where id = p_task_id for update;
  if not found then raise exception 'Task not found' using errcode = 'P0002'; end if;
  v := proj_lock_project(t.project_id);
  perform proj_require_open_project(v);
  if proj_task_actor_role(t) is null then raise exception 'Only the assignee, the department head or the Project Manager can block this task' using errcode = '42501'; end if;
  if t.status in ('done', 'cancelled', 'deferred') then raise exception 'A % task cannot be blocked', t.status using errcode = '23514'; end if;
  if length(btrim(coalesce(p_reason, ''))) = 0 then raise exception 'Say what is blocking the task' using errcode = '22023'; end if;
  if p_unblock_owner is null and length(btrim(coalesce(p_unblock_action, ''))) = 0 then
    raise exception 'Say who or what action will unblock it' using errcode = '22023';
  end if;
  if p_unblock_owner is not null and not exists (select 1 from proj_project_members where project_id = v.id and user_id = p_unblock_owner and removed_at is null) then
    raise exception 'The person who can unblock it must be a member of the project' using errcode = '22023';
  end if;
  update proj_tasks set blocked_at = now(), blocked_reason = btrim(p_reason), unblock_owner_id = p_unblock_owner,
         unblock_action = nullif(btrim(p_unblock_action), ''), version = version + 1 where id = t.id;
  perform proj_task_event(t.id, v.id, 'blocked', null, btrim(p_reason), p_unblock_action);
  perform proj_notify(v.id, coalesce(p_unblock_owner, v.pm_user_id), 'project_task_blocked',
    jsonb_build_object('name', v.name, 'reference', v.reference, 'task_id', t.id, 'task', t.title, 'reason', btrim(p_reason)), 'task:' || t.id || ':blocked:' || (t.version + 1));
  -- Also tell the Project Manager when someone else was named (the PM is accountable for the project). Never twice to the same person, never the reporter.
  if p_unblock_owner is not null and v.pm_user_id is not null and v.pm_user_id is distinct from p_unblock_owner then
    select coalesce(nullif(btrim(full_name), ''), split_part(email, '@', 1)) into v_unblocker from profiles where id = p_unblock_owner;
    perform proj_notify(v.id, v.pm_user_id, 'project_task_blocked',
      jsonb_build_object('name', v.name, 'reference', v.reference, 'task_id', t.id, 'task', t.title, 'reason', btrim(p_reason), 'fyi', true, 'unblocker', coalesce(v_unblocker, 'a colleague')),
      'task:' || t.id || ':blocked:' || (t.version + 1));
  end if;
end;
$$;
-- ==== END MIGRATION 20261216000900_proj_block_task_notifies_pm.sql ====

-- ==== BEGIN MIGRATION 20261216000910_module_access_managers.sql (4452 bytes, sha256 c38418dac42c3e6d159e364312a67ef02378df8cb164add2f3b04f0a5c101677) ====
-- Who can grant access to a module, for the people who do not have it (completion pass, B12 / U-13). ADDITIVE: adds one read-only function; no table, column,
-- policy, trigger or privilege on anything existing changes, and no data changes.
--
-- WHY. A person who is denied a module (Sales, Projects, Inventory, Project Budget & Expenses) was told "Ask a founder" with no name. The grant tables are readable
-- only by the people who hold access, so a person without it could not look the names up.
--
-- WHAT. module_access_managers(p_module) returns ONE row per person who can manage that module's access in the CALLER'S OWN COMPANY, and nothing else:
--     user_id (the person's identifier) and display_name.
--   * The company is derived from the caller (their employee record). There is no company argument, so nobody can ask about another company; a caller with no employee
--     record gets no rows.
--   * "Can manage access" is exactly what the module's own grant functions check: Sales, Projects and Inventory: a founder, or a holder of manage_access
--     (the *_has_capability helpers); Project Budget & Expenses: a holder of manage_access (a budget grant has no founder right). Only active, un-revoked grants of that
--     company count, held by an ACTIVE person (an inactive account is never listed, the same join the helpers use).
--   * Module grants are always for one company (company_id is required; they have no country or global form), so unlike role grants there are no country-limited or
--     company-less holders to consider here: a holder of ANOTHER company is never returned.
--   * Not returned: emails, the grant row, capabilities, who granted it, any other company's holders, or any other personnel data.
--   * Callable by any signed-in person, with or without a grant; a signed-out caller is refused; an unknown module is refused.
-- Who may grant, revoke or see grants, and every other function, are unchanged.
-- Rollback: supabase/manual-sql/modaccess_90_rollback.sql drops the function.

create or replace function module_access_managers(p_module text)
returns table (user_id uuid, display_name text)
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_company uuid;
  v_ids uuid[] := '{}';
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if p_module is null or p_module not in ('sales', 'projects', 'inventory', 'budget') then
    raise exception 'Unknown module' using errcode = '22023';
  end if;
  -- Only the caller's own company, and only for an active caller.
  select e.company_id into v_company
    from employees e join profiles me on me.id = auth.uid() and me.is_active
   where e.user_id = auth.uid() and e.deleted_at is null
   limit 1;
  if v_company is null then return; end if;

  -- One branch per module, so a module that is not installed here cannot break the others.
  if p_module = 'sales' then
    select coalesce(array_agg(distinct g.user_id), '{}') into v_ids from crm_company_grants g
     where g.company_id = v_company and g.revoked_at is null and ('founder' = any (g.capabilities) or 'manage_access' = any (g.capabilities));
  elsif p_module = 'projects' then
    select coalesce(array_agg(distinct g.user_id), '{}') into v_ids from proj_company_grants g
     where g.company_id = v_company and g.revoked_at is null and ('founder' = any (g.capabilities) or 'manage_access' = any (g.capabilities));
  elsif p_module = 'inventory' then
    select coalesce(array_agg(distinct g.user_id), '{}') into v_ids from inv_company_grants g
     where g.company_id = v_company and g.revoked_at is null and ('founder' = any (g.capabilities) or 'manage_access' = any (g.capabilities));
  else
    select coalesce(array_agg(distinct g.user_id), '{}') into v_ids from pbx_company_grants g
     where g.company_id = v_company and g.revoked_at is null and 'manage_access' = any (g.capabilities);
  end if;

  return query
    select h.uid,
           coalesce(nullif(btrim(p.full_name), ''), (select nullif(btrim(e.first_name || ' ' || e.last_name), '') from employees e where e.user_id = h.uid and e.deleted_at is null limit 1), 'A colleague')
      from unnest(v_ids) as h(uid)
      join profiles p on p.id = h.uid and p.is_active
     order by 2, 1;
end;
$$;

revoke all on function module_access_managers(text) from public, anon;
grant execute on function module_access_managers(text) to authenticated;
-- ==== END MIGRATION 20261216000910_module_access_managers.sql ====

-- ==== BEGIN MIGRATION 20261217000100_inv_project_notes.sql (53196 bytes, sha256 16e0f24cdb20cac36915b16c83855c25062529b114486d8905684e199d9c671e) ====
-- Launch package 3a: dispatch notes and return checklists (database layer). C1, C2, C7.
--
-- WHAT THIS ADDS. When the warehouse records a dispatch to a project (or a return from it), the system can keep a frozen, numbered copy of exactly what was
-- recorded (UAE-D-00017 for a dispatch note, UAE-RT-00005 for a return checklist), show it to the project's Project Manager (PM), and let the PM acknowledge it or report
-- a difference. The recorded movement stays the ONLY authority for where equipment is. A note, an acknowledgement or a dispute never moves stock, never changes
-- availability, custody, reservations or booking conflicts, never rewrites movement history, and never creates a write-off, deduction or penalty.
--
--   * Counters 'dispatch_note' and 'return_note' (numbers <ref>-D-nnnnn and <ref>-RT-nnnnn, per company of the WAREHOUSE LOCATION, never reset, no gaps: a number is
--     taken inside the movement transaction and rolls back with it). inv_next_code gains the two kinds; every other kind behaves exactly as before.
--   * inv_project_notes: one frozen row per movement (header snapshot + payload + hash). EVERY column is frozen: a guard trigger refuses any UPDATE, DELETE or TRUNCATE for
--     every role (the service role included). A correction is a NEW note that cites the old one; the old note is never altered.
--   * inv_project_note_events: append-only history (acknowledged, difference reported / withdrawn, resolved, correction cited). Same guard.
--   * inv_project_note_status: the current state of each note, derived from its own events (waiting for the PM, acknowledged, difference open, superseded). The pending
--     action therefore lives on the note record and can be listed per project and in "Needs me"; no notice or approval is involved.
--   * inv_make_project_note(movement) (internal), inv_ack_project_note (PM / acting PM / Projects founder, checked at the moment of the click, capacity recorded),
--     inv_resolve_note_difference (warehouse operator at the location only), inv_notes_waiting_for_me, inv_set_project_notes (founder switch).
--   * The per-company switch inv_company_settings.project_notes_enabled is OFF by default. With it off, inv_dispatch_to_project and inv_return_from_project behave
--     exactly as before: they only gain one guarded call that is skipped. With it on, the note is made INSIDE the movement transaction, so there is never a dispatch without
--     its note or a note without its dispatch; if the note cannot be made, the movement is refused and nothing is recorded.
--
-- Prerequisites: Inventory (20261201*) and Projects (20261120*) migrations. Additive and idempotent (safe to run twice). Nothing is read from or written to HR tables.

-- -----------------------------------------------------------------------------
-- The per-company switch (C7). Off by default; changes are audited by the existing inv_company_settings audit trigger.
-- -----------------------------------------------------------------------------
alter table inv_company_settings add column if not exists project_notes_enabled boolean not null default false;

-- -----------------------------------------------------------------------------
-- Counters (C1): the two new kinds
-- -----------------------------------------------------------------------------
alter table inv_reference_counters drop constraint if exists inv_reference_counters_kind_check;
alter table inv_reference_counters add constraint inv_reference_counters_kind_check
  check (kind in ('unit', 'stock', 'request', 'transfer', 'movement', 'count', 'dispatch_note', 'return_note'));

-- Identical to the earlier definition except for the two new kinds: UAE-D-00001 (dispatch notes), UAE-RT-00001 (return checklists).
create or replace function inv_next_code(p_company_id uuid, p_kind text)
returns text
language plpgsql security definer
set search_path = public
as $$
declare
  v_code text;
  v_n bigint;
  v_letter text := case p_kind when 'unit' then 'E' when 'stock' then 'S' when 'request' then 'R' when 'transfer' then 'T'
                              when 'movement' then 'M' when 'count' then 'C' when 'dispatch_note' then 'D' when 'return_note' then 'RT' end;
begin
  if v_letter is null then raise exception 'Unknown code kind %', p_kind using errcode = '22023'; end if;
  select reference_code into v_code from inv_company_settings where company_id = p_company_id;
  if v_code is null then
    raise exception 'An Inventory reference code has not been set for this company yet. A founder sets it under Manage.' using errcode = '23514';
  end if;
  insert into inv_reference_counters (company_id, kind, last_value) values (p_company_id, p_kind, 1)
  on conflict (company_id, kind) do update set last_value = inv_reference_counters.last_value + 1
  returning last_value into v_n;
  return v_code || '-' || v_letter || '-' || lpad(v_n::text, 5, '0');
end;
$$;

-- -----------------------------------------------------------------------------
-- Frozen notes and append-only events (C1)
-- -----------------------------------------------------------------------------
create table if not exists inv_project_notes (
  id                 uuid primary key default gen_random_uuid(),
  company_id         uuid not null references companies(id),            -- the company of the WAREHOUSE LOCATION (same as the movement); it numbers the note
  kind               text not null check (kind in ('dispatch', 'return')),
  note_no            text not null unique,                              -- UAE-D-00017 / UAE-RT-00005
  movement_id        uuid not null unique references inv_movements(id), -- one note per movement
  movement_code      text not null,                                     -- the ledger reference (UAE-M-00031)
  project_id         uuid not null references proj_projects(id),
  project_company_id uuid not null references companies(id),            -- printed too when it differs from company_id (cross-company sharing)
  project_ref        text not null,
  project_name       text not null,
  destination        text,                                              -- the project's site text at the moment of recording
  site_timezone      text,
  location_id        uuid not null references inv_locations(id),        -- the warehouse location that recorded it (who may resolve a difference)
  location_name      text not null,
  location_timezone  text not null,                                     -- the ledger stores only UTC; this is the zone the times are shown in
  recorded_by        uuid not null references auth.users(id),
  recorded_by_name   text not null,
  recorded_by_role   text,
  pm_user_id_at_time uuid references auth.users(id),
  pm_name_at_time    text,
  occurred_at        timestamptz not null,
  expected_return_at timestamptz,
  request_id         uuid,
  request_code       text,
  replaces_note_id   uuid references inv_project_notes(id),             -- a correction note cites the note it replaces
  payload            jsonb not null check (jsonb_typeof(payload) = 'object'),   -- the frozen lines (and, for a return, the project totals)
  payload_hash       text not null,
  created_at         timestamptz not null default now(),
  constraint inv_project_notes_no_format check (note_no ~ case kind when 'dispatch' then '^[A-Z]{2,5}-D-[0-9]{5,}$' else '^[A-Z]{2,5}-RT-[0-9]{5,}$' end),
  constraint inv_project_notes_not_self check (replaces_note_id is null or replaces_note_id <> id)
);
create index if not exists idx_inv_project_notes_project on inv_project_notes(project_id, created_at desc);
create index if not exists idx_inv_project_notes_company on inv_project_notes(company_id, created_at desc);
create index if not exists idx_inv_project_notes_replaces on inv_project_notes(replaces_note_id) where replaces_note_id is not null;

create table if not exists inv_project_note_events (
  id                 uuid primary key default gen_random_uuid(),
  seq                bigint generated always as identity,               -- the order of events within a note
  note_id            uuid not null references inv_project_notes(id),
  company_id         uuid not null references companies(id),
  project_id         uuid not null references proj_projects(id),
  event              text not null check (event in ('acknowledged', 'difference_reported', 'difference_withdrawn', 'resolved_record_stands', 'resolved_corrected', 'correction_of')),
  by_user            uuid not null references auth.users(id),
  by_name            text not null,
  capacity           text not null check (capacity in ('pm', 'acting_pm', 'projects_founder', 'warehouse')),
  at                 timestamptz not null default now(),
  reason             text,                                              -- difference_reported only
  lines              jsonb check (lines is null or jsonb_typeof(lines) = 'array'),   -- difference_reported: the line numbers of the note
  comment            text check (comment is null or length(comment) <= 2000),
  linked_note_id     uuid references inv_project_notes(id),
  linked_movement_id uuid references inv_movements(id),
  constraint inv_project_note_events_reason check ((event = 'difference_reported') = (reason is not null))
);
create unique index if not exists uq_inv_project_note_events_seq on inv_project_note_events(seq);
create index if not exists idx_inv_project_note_events_note on inv_project_note_events(note_id, seq);
create index if not exists idx_inv_project_note_events_project on inv_project_note_events(project_id);

-- Nothing about a note or its history is ever edited or deleted, by anyone (a table owner or the service role included): the same guard on both tables.
create or replace function inv_project_notes_frozen()
returns trigger
language plpgsql
as $$
begin
  raise exception 'A dispatch note or return checklist and its history are never edited or deleted. A correction is a new note that cites the old one.' using errcode = '55000';
end;
$$;
drop trigger if exists inv_project_notes_frozen_row on inv_project_notes;
create trigger inv_project_notes_frozen_row before update or delete on inv_project_notes for each row execute function inv_project_notes_frozen();
drop trigger if exists inv_project_notes_frozen_truncate on inv_project_notes;
create trigger inv_project_notes_frozen_truncate before truncate on inv_project_notes for each statement execute function inv_project_notes_frozen();
drop trigger if exists inv_project_note_events_frozen_row on inv_project_note_events;
create trigger inv_project_note_events_frozen_row before update or delete on inv_project_note_events for each row execute function inv_project_notes_frozen();
drop trigger if exists inv_project_note_events_frozen_truncate on inv_project_note_events;
create trigger inv_project_note_events_frozen_truncate before truncate on inv_project_note_events for each statement execute function inv_project_notes_frozen();

-- Who reads what: project members and the Projects founder of the project's company (proj_can_view_details), and Inventory warehouse / view_stock holders of the
-- warehouse company (they read the ledger already). A Project Manager needs NO Inventory grant to read the notes of their project, and still cannot read the ledger.
alter table inv_project_notes enable row level security;
drop policy if exists inv_project_notes_select on inv_project_notes;
create policy inv_project_notes_select on inv_project_notes for select
  using (proj_can_view_details(project_id) or inv_can_view_stock(company_id));
alter table inv_project_note_events enable row level security;
drop policy if exists inv_project_note_events_select on inv_project_note_events;
create policy inv_project_note_events_select on inv_project_note_events for select
  using (proj_can_view_details(project_id) or inv_can_view_stock(company_id));

-- The current state of every note, derived from its own events and read under the CALLER's row-level security.
--   state     waiting_for_pm | acknowledged | difference_open | superseded
--   awaiting  'pm' (the note needs the PM's acknowledgement), 'warehouse' (a difference is open and the warehouse owns the next step), or null
create or replace view inv_project_note_status with (security_invoker = true) as
select n.id as note_id, n.company_id, n.project_id, n.kind, n.note_no, n.created_at,
       coalesce(n.replaces_note_id, co.linked_note_id) as replaces_note_id,
       sup.superseded_by_note_id,
       ak.at as acknowledged_at, ak.by_user as acknowledged_by, ak.by_name as acknowledged_by_name, ak.capacity as acknowledged_capacity,
       case when df.event = 'difference_reported' then 'open'
            when df.event in ('resolved_record_stands', 'resolved_corrected') then 'resolved'
            when df.event = 'difference_withdrawn' then 'withdrawn'
            else 'none' end as difference_state,
       case when df.event = 'difference_reported' then df.at end as difference_reported_at,
       case when df.event = 'difference_reported' then df.reason end as difference_reason,
       case when df.event = 'difference_reported' then df.lines end as difference_lines,
       case when sup.superseded_by_note_id is not null then null
            when df.event = 'difference_reported' then 'warehouse'
            when ak.at is null then 'pm' end as awaiting,
       case when df.event = 'difference_reported' then df.at else n.created_at end as pending_since,
       case when sup.superseded_by_note_id is not null then 'superseded'
            when df.event = 'difference_reported' then 'difference_open'
            when ak.at is not null then 'acknowledged'
            else 'waiting_for_pm' end as state
from inv_project_notes n
left join lateral (select e.* from inv_project_note_events e where e.note_id = n.id and e.event = 'acknowledged' order by e.seq desc limit 1) ak on true
left join lateral (select e.* from inv_project_note_events e where e.note_id = n.id
                    and e.event in ('difference_reported', 'difference_withdrawn', 'resolved_record_stands', 'resolved_corrected') order by e.seq desc limit 1) df on true
left join lateral (select e.linked_note_id from inv_project_note_events e where e.note_id = n.id and e.event = 'correction_of' order by e.seq asc limit 1) co on true
left join lateral (select coalesce(
                      (select e.linked_note_id from inv_project_note_events e where e.note_id = n.id and e.event = 'resolved_corrected' and e.linked_note_id is not null order by e.seq desc limit 1),
                      (select n2.id from inv_project_notes n2 where n2.replaces_note_id = n.id order by n2.created_at limit 1)) as superseded_by_note_id) sup on true;

-- -----------------------------------------------------------------------------
-- The switch (C7): internal reader used by the two movement functions, and the founder's setter.
-- -----------------------------------------------------------------------------
create or replace function inv_project_notes_enabled(p_company_id uuid)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select coalesce((select s.project_notes_enabled from inv_company_settings s where s.company_id = p_company_id), false);
$$;

create or replace function inv_set_project_notes(p_company_id uuid, p_enabled boolean)
returns void
language plpgsql security definer
set search_path = public
as $$
begin
  perform inv_require_user();
  if not inv_is_founder(p_company_id) then
    raise exception 'Only an Inventory founder can switch dispatch notes and return checklists on or off' using errcode = '42501';
  end if;
  if p_enabled is null then raise exception 'Say whether to switch them on or off' using errcode = '22023'; end if;
  update inv_company_settings set project_notes_enabled = p_enabled, updated_by = auth.uid() where company_id = p_company_id;
  if not found then raise exception 'Set the reference code first' using errcode = '23514'; end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- Making a note (C2). INTERNAL: called only by inv_dispatch_to_project and inv_return_from_project (inside their transaction) and by
-- inv_resolve_note_difference; no signed-in user can call it. It reads the movement that was just recorded (its immutable lines) and snapshots every name, serial
-- and date, so later edits of the catalogue, the project or the warehouse never change an issued note. Idempotent: one note per movement, a second call
-- returns the existing note and takes no number. Any failure refuses the whole movement (nothing is recorded) and says why.
-- -----------------------------------------------------------------------------
create or replace function inv_make_project_note(p_movement_id uuid, p_replaces_note_id uuid default null)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  m inv_movements; pr proj_projects; l inv_locations; ex inv_project_notes; d proj_project_details; q inv_requests;
  v_kind text; v_loc uuid; v_id uuid := gen_random_uuid(); v_no text; v_lines jsonb; v_totals jsonb; v_payload jsonb;
  v_pm_name text; v_rec_name text; v_rec_role text;
begin
  begin
    select * into m from inv_movements where id = p_movement_id;
    if m.id is null then raise exception 'Unknown movement'; end if;
    if m.kind not in ('dispatch_project', 'return_project') then raise exception 'Only a dispatch to a project or a return from one has a note'; end if;
    select * into ex from inv_project_notes where movement_id = m.id;
    if ex.id is not null then
      return jsonb_build_object('note_id', ex.id, 'note_no', ex.note_no, 'created', false);
    end if;
    v_kind := case m.kind when 'dispatch_project' then 'dispatch' else 'return' end;
    v_loc := case v_kind when 'dispatch' then m.from_location_id else m.to_location_id end;
    select * into pr from proj_projects where id = m.project_id;
    select * into l from inv_locations where id = v_loc;
    select * into d from proj_project_details where project_id = pr.id;
    if m.request_id is not null then select * into q from inv_requests where id = m.request_id; end if;
    select coalesce(nullif(btrim(p.full_name), ''), split_part(p.email, '@', 1)) into v_pm_name from profiles p where p.id = pr.pm_user_id;
    select coalesce(nullif(btrim(p.full_name), ''), split_part(p.email, '@', 1)) into v_rec_name from profiles p where p.id = m.performed_by;
    select case when 'founder' = any (g.capabilities) then 'Inventory founder' when 'warehouse' = any (g.capabilities) then 'Warehouse operator' end into v_rec_role
      from inv_company_grants g where g.user_id = m.performed_by and g.company_id = m.company_id and g.revoked_at is null;

    -- The lines: units one by one (equipment ID and serial from now), counted stock merged per item and condition.
    select coalesce(jsonb_agg(x.obj || jsonb_build_object('n', x.rn) order by x.rn), '[]'::jsonb) into v_lines
    from (
      select row_number() over (order by s.grp, s.name, s.ord) as rn, s.obj
      from (
        select 0 as grp, i.name, u.code as ord,
               jsonb_build_object('item_id', i.id, 'item_name', i.name, 'manufacturer', i.manufacturer, 'model', i.model, 'specification', i.specification,
                                  'unit_id', u.id, 'equipment_id', u.code, 'serial', u.serial_number, 'qty', 1, 'uom', i.unit_of_measure,
                                  'condition', coalesce(ml.condition_to, ml.condition_from),
                                  'outcome', case when coalesce(ml.condition_to, ml.condition_from) in ('good', 'fair') then 'available' else 'held' end) as obj
        from inv_movement_lines ml
        join inv_units u on u.id = ml.unit_id
        join inv_items i on i.id = ml.item_id
        where ml.movement_id = m.id and ml.unit_id is not null
        union all
        select 1, i.name, coalesce(coalesce(ml.condition_to, ml.condition_from), ''),
               jsonb_build_object('item_id', i.id, 'item_name', i.name, 'manufacturer', i.manufacturer, 'model', i.model, 'specification', i.specification,
                                  'unit_id', null, 'equipment_id', null, 'serial', null, 'qty', trim_scale(sum(ml.qty)), 'uom', i.unit_of_measure,
                                  'condition', coalesce(ml.condition_to, ml.condition_from),
                                  'outcome', case when coalesce(ml.condition_to, ml.condition_from) in ('good', 'fair') then 'available' else 'held' end)
        from inv_movement_lines ml
        join inv_items i on i.id = ml.item_id
        where ml.movement_id = m.id and ml.unit_id is null
        group by i.id, i.name, i.manufacturer, i.model, i.specification, i.unit_of_measure, coalesce(ml.condition_to, ml.condition_from)
      ) s
    ) x;
    if jsonb_array_length(v_lines) = 0 then raise exception 'The movement has no lines'; end if;
    if v_kind = 'dispatch' then
      -- the condition outcome is a return notion; a dispatch line carries only its condition
      select jsonb_agg(e - 'outcome' order by (e->>'n')::int) into v_lines from jsonb_array_elements(v_lines) e;
    end if;
    v_payload := jsonb_build_object('schema', 1, 'lines', v_lines);

    if v_kind = 'return' then
      -- Project totals after this return, from the ledger: everything that went onto the project, everything that came off it before this movement, what this
      -- movement took off, and what the project holds now (units exactly; counted stock for the project, never per request line).
      select coalesce(jsonb_agg(t.obj order by t.name), '[]'::jsonb) into v_totals
      from (
        select f.name, jsonb_build_object('item_id', f.item_id, 'item_name', f.name, 'uom', f.uom, 'individual', f.individual,
                 'sent', trim_scale(f.sent), 'returned_before', trim_scale(f.returned_before), 'received_now', trim_scale(f.received_now), 'still_out', trim_scale(f.still_out)) as obj
        from (
          select i.id as item_id, i.name, i.unit_of_measure as uom, i.tracking in ('individual', 'kit') as individual,
                 fl.sent, fl.returned_before, fl.received_now,
                 coalesce((select count(*) from inv_units u where u.item_id = i.id and u.custody_kind = 'project' and u.project_id = pr.id), 0)
                 + coalesce((select sum(b.qty) from inv_balances b where b.item_id = i.id and b.holder_kind = 'project' and b.project_id = pr.id), 0) as still_out
          from (
            select ml.item_id,
                   sum(case when ml.to_kind = 'project' and ml.to_project_id = pr.id then ml.qty else 0 end) as sent,
                   sum(case when ml.from_kind = 'project' and ml.from_project_id = pr.id and ml.movement_id <> m.id then ml.qty else 0 end) as returned_before,
                   sum(case when ml.movement_id = m.id then ml.qty else 0 end) as received_now
            from inv_movement_lines ml
            where ml.to_project_id = pr.id or ml.from_project_id = pr.id
            group by ml.item_id
          ) fl
          join inv_items i on i.id = fl.item_id
        ) f
        where f.received_now > 0 or f.still_out > 0
      ) t;
      v_payload := v_payload || jsonb_build_object('totals', v_totals);
    end if;

    v_no := inv_next_code(m.company_id, case v_kind when 'dispatch' then 'dispatch_note' else 'return_note' end);
    insert into inv_project_notes (id, company_id, kind, note_no, movement_id, movement_code, project_id, project_company_id, project_ref, project_name, destination, site_timezone,
        location_id, location_name, location_timezone, recorded_by, recorded_by_name, recorded_by_role, pm_user_id_at_time, pm_name_at_time, occurred_at, expected_return_at,
        request_id, request_code, replaces_note_id, payload, payload_hash)
    values (v_id, m.company_id, v_kind, v_no, m.id, m.code, pr.id, pr.company_id, pr.reference, pr.name, nullif(btrim(d.location), ''), d.site_timezone,
        l.id, l.name, l.timezone, m.performed_by, coalesce(v_rec_name, 'Unknown'), v_rec_role, pr.pm_user_id, v_pm_name, m.occurred_at,
        case when v_kind = 'dispatch' then m.expected_return_at end,
        m.request_id, q.code, p_replaces_note_id, v_payload, md5(v_payload::text));
    return jsonb_build_object('note_id', v_id, 'note_no', v_no, 'created', true);
  exception when others then
    raise exception 'The % note could not be made, so nothing was recorded (%). Try again, or ask an Inventory founder to switch dispatch notes off for this company.',
      case when v_kind = 'return' then 'return checklist' else 'dispatch' end, sqlerrm using errcode = '23514';
  end;
end;
$$;

-- -----------------------------------------------------------------------------
-- The Project Manager's answer (C2). Non-blocking: nothing waits for it. Who may act is decided HERE, at the moment of the call: the current PM, an acting PM
-- whose period has not expired, or a Projects founder of the project's company (proj_can_manage), and the capacity is recorded. Actions:
--   acknowledge        "I acknowledge this recorded list". A second call returns the original acknowledgement and records nothing.
--   report_difference  lines (the note's line numbers) + a reason (+ a comment, required for 'other'); the warehouse owns the next step. Custody and availability do not change.
--   withdraw           withdraw the open report.
-- p_key (optional, 8 to 120 characters) makes a retried call return the original answer, the same way the movement functions do.
-- -----------------------------------------------------------------------------
create or replace function inv_ack_project_note(p_note_id uuid, p_action text, p_lines jsonb default null, p_comment text default null,
                                                p_reason text default null, p_key text default null)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  n inv_project_notes; pr proj_projects; s inv_project_note_status; v_cap text; v_name text; v_prev jsonb; v_result jsonb;
  v_comment text := nullif(btrim(coalesce(p_comment, '')), ''); v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_count int; v_ok_reasons text[]; v_lines jsonb := null; v_ln jsonb; v_seen int[] := '{}'; v_num int; v_event inv_project_note_events;
begin
  perform inv_require_user();
  if p_action is null or p_action not in ('acknowledge', 'report_difference', 'withdraw') then
    raise exception 'Choose acknowledge, report a difference or withdraw' using errcode = '22023';
  end if;
  select * into n from inv_project_notes where id = p_note_id for update;
  if n.id is null then raise exception 'Note not found' using errcode = 'P0002'; end if;
  select * into pr from proj_projects where id = n.project_id;
  if proj_is_pm(n.project_id) then
    v_cap := case when pr.pm_user_id = auth.uid() then 'pm' else 'acting_pm' end;
  elsif proj_is_founder(pr.company_id) then
    v_cap := 'projects_founder';
  else
    raise exception 'Only the project''s Project Manager, an acting Project Manager or a Projects founder can answer this note' using errcode = '42501';
  end if;
  select coalesce(nullif(btrim(p.full_name), ''), split_part(p.email, '@', 1)) into v_name from profiles p where p.id = auth.uid();
  v_name := coalesce(v_name, 'Unknown');

  if p_key is not null then
    v_prev := inv_idem_begin(n.company_id, p_key, 'note_action', jsonb_build_object('note', p_note_id, 'action', p_action, 'lines', p_lines, 'comment', v_comment, 'reason', v_reason));
    if v_prev is not null then return v_prev; end if;
  end if;

  select * into s from inv_project_note_status where note_id = n.id;
  if s.superseded_by_note_id is not null then
    raise exception '% has been replaced by a newer note. Answer the newer note', n.note_no using errcode = '23514';
  end if;

  if p_action = 'acknowledge' then
    if s.acknowledged_at is not null then
      v_result := jsonb_build_object('note_id', n.id, 'note_no', n.note_no, 'event', 'acknowledged', 'by_name', s.acknowledged_by_name, 'capacity', s.acknowledged_capacity,
                                     'at', s.acknowledged_at, 'replayed', true);
      if p_key is not null then update inv_idempotency set result = v_result where company_id = n.company_id and idem_key = btrim(p_key); end if;
      return v_result;
    end if;
    if s.difference_state = 'open' then
      raise exception 'A difference is open on % and the warehouse is looking at it. Withdraw it first, or wait for the warehouse to answer', n.note_no using errcode = '23514';
    end if;
    insert into inv_project_note_events (note_id, company_id, project_id, event, by_user, by_name, capacity, comment)
    values (n.id, n.company_id, n.project_id, 'acknowledged', auth.uid(), v_name, v_cap, v_comment) returning * into v_event;
  elsif p_action = 'report_difference' then
    if length(coalesce(v_comment, '')) > 2000 then raise exception 'The comment is too long (2000 characters at most)' using errcode = '22023'; end if;
    v_ok_reasons := case n.kind when 'dispatch' then array['not_on_site', 'quantity_differs', 'different_item', 'condition_differs', 'other']
                                else array['not_returned', 'quantity_differs', 'missing_from_list', 'condition_differs', 'other'] end;
    if v_reason is null or not (v_reason = any (v_ok_reasons)) then
      raise exception 'Say what is different' using errcode = '22023';
    end if;
    if v_reason = 'other' and v_comment is null then raise exception 'Describe the difference in the comment' using errcode = '22023'; end if;
    v_count := jsonb_array_length(n.payload->'lines');
    if p_lines is not null and jsonb_typeof(p_lines) <> 'array' then raise exception 'The lines must be a list' using errcode = '22023'; end if;
    if p_lines is not null then
      for v_ln in select x from jsonb_array_elements(p_lines) x loop
        if jsonb_typeof(v_ln) <> 'number' or (v_ln #>> '{}') !~ '^[0-9]+$' then raise exception 'Name the lines by their numbers' using errcode = '22023'; end if;
        v_num := (v_ln #>> '{}')::int;
        if v_num < 1 or v_num > v_count then raise exception 'This note has no line %', v_num using errcode = '22023'; end if;
        if v_num = any (v_seen) then raise exception 'Line % is listed twice', v_num using errcode = '22023'; end if;
        v_seen := v_seen || v_num;
      end loop;
      v_lines := p_lines;
    end if;
    if coalesce(jsonb_array_length(v_lines), 0) = 0 and not (n.kind = 'return' and v_reason = 'missing_from_list') then
      raise exception 'Tick the line or lines that differ' using errcode = '22023';
    end if;
    if s.difference_state = 'open' then
      raise exception 'A difference is already open on % and the warehouse is looking at it', n.note_no using errcode = '23514';
    end if;
    insert into inv_project_note_events (note_id, company_id, project_id, event, by_user, by_name, capacity, reason, lines, comment)
    values (n.id, n.company_id, n.project_id, 'difference_reported', auth.uid(), v_name, v_cap, v_reason, coalesce(v_lines, '[]'::jsonb), v_comment) returning * into v_event;
  else
    if s.difference_state <> 'open' then raise exception 'There is no open difference on % to withdraw', n.note_no using errcode = '23514'; end if;
    insert into inv_project_note_events (note_id, company_id, project_id, event, by_user, by_name, capacity, comment)
    values (n.id, n.company_id, n.project_id, 'difference_withdrawn', auth.uid(), v_name, v_cap, v_comment) returning * into v_event;
  end if;
  v_result := jsonb_build_object('note_id', n.id, 'note_no', n.note_no, 'event', v_event.event, 'by_name', v_event.by_name, 'capacity', v_event.capacity,
                                 'at', v_event.at, 'replayed', false);
  if p_key is not null then update inv_idempotency set result = v_result where company_id = n.company_id and idem_key = btrim(p_key); end if;
  return v_result;
end;
$$;

-- -----------------------------------------------------------------------------
-- The warehouse's answer to an open difference (C2). Only an operator of the location that recorded the note (a founder of its company, or a warehouse operator
-- assigned to that location or with cross-location rights), and only while Inventory is on. Two outcomes, neither of which touches stock by itself:
--   record_stands   the warehouse confirms the recorded list is right.
--   corrected       the warehouse has corrected the ledger by the EXISTING actions (reverse and record again, mark missing or found, check condition) and names the
--                   movement. When that movement is a dispatch / return of the same kind for the same project, its note is the NEW note that cites this one (made now
--                   if it has none); this note is never altered and shows "Superseded by ...".
-- A comment is required. Nothing here records a movement, deducts, writes off or penalises anyone.
-- -----------------------------------------------------------------------------
create or replace function inv_resolve_note_difference(p_note_id uuid, p_resolution text, p_comment text, p_linked_movement_id uuid default null, p_key text default null)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  n inv_project_notes; s inv_project_note_status; lm inv_movements; n2 inv_project_notes; v_name text; v_prev jsonb; v_result jsonb; v_event inv_project_note_events;
  v_comment text := nullif(btrim(coalesce(p_comment, '')), ''); v_new uuid := null; v_made jsonb; v_same_kind boolean;
begin
  perform inv_require_user();
  if p_resolution is null or p_resolution not in ('record_stands', 'corrected') then
    raise exception 'Choose "the record stands" or "corrected"' using errcode = '22023';
  end if;
  select * into n from inv_project_notes where id = p_note_id for update;
  if n.id is null then raise exception 'Note not found' using errcode = 'P0002'; end if;
  if not inv_can_operate(n.location_id) then
    raise exception 'Only a warehouse operator at % can answer a difference on this note', n.location_name using errcode = '42501';
  end if;
  perform inv_require_enabled(n.company_id);
  if v_comment is null then raise exception 'Say what the warehouse found, in the comment' using errcode = '22023'; end if;
  if length(v_comment) > 2000 then raise exception 'The comment is too long (2000 characters at most)' using errcode = '22023'; end if;
  select coalesce(nullif(btrim(p.full_name), ''), split_part(p.email, '@', 1)) into v_name from profiles p where p.id = auth.uid();
  v_name := coalesce(v_name, 'Unknown');

  if p_key is not null then
    v_prev := inv_idem_begin(n.company_id, p_key, 'note_resolve', jsonb_build_object('note', p_note_id, 'resolution', p_resolution, 'comment', v_comment, 'movement', p_linked_movement_id));
    if v_prev is not null then return v_prev; end if;
  end if;

  select * into s from inv_project_note_status where note_id = n.id;
  if s.difference_state <> 'open' then raise exception 'There is no open difference on % to answer', n.note_no using errcode = '23514'; end if;

  if p_resolution = 'record_stands' then
    if p_linked_movement_id is not null then raise exception 'Name a movement only when the record was corrected' using errcode = '22023'; end if;
    insert into inv_project_note_events (note_id, company_id, project_id, event, by_user, by_name, capacity, comment)
    values (n.id, n.company_id, n.project_id, 'resolved_record_stands', auth.uid(), v_name, 'warehouse', v_comment) returning * into v_event;
  else
    if p_linked_movement_id is null then raise exception 'Name the movement that corrected the record' using errcode = '22023'; end if;
    select * into lm from inv_movements where id = p_linked_movement_id;
    if lm.id is null or lm.company_id <> n.company_id then raise exception 'Unknown movement' using errcode = '22023'; end if;
    if lm.id = n.movement_id then raise exception 'The correcting movement must be a later movement, not the one this note records' using errcode = '23514'; end if;
    if lm.recorded_at < (select recorded_at from inv_movements where id = n.movement_id) then
      raise exception 'The correcting movement must have been recorded after the one this note records' using errcode = '23514';
    end if;
    v_same_kind := lm.kind = case n.kind when 'dispatch' then 'dispatch_project' else 'return_project' end;
    if v_same_kind and lm.project_id is distinct from n.project_id then raise exception 'That movement is for another project' using errcode = '23514'; end if;
    if v_same_kind then
      select * into n2 from inv_project_notes where movement_id = lm.id;
      if n2.id is null then
        v_made := inv_make_project_note(lm.id, n.id);                -- the new note cites this one
        v_new := (v_made->>'note_id')::uuid;
      else
        v_new := n2.id;
        if n2.replaces_note_id is null and not exists (select 1 from inv_project_note_events where note_id = n2.id and event = 'correction_of') then
          insert into inv_project_note_events (note_id, company_id, project_id, event, by_user, by_name, capacity, comment, linked_note_id, linked_movement_id)
          values (n2.id, n2.company_id, n2.project_id, 'correction_of', auth.uid(), v_name, 'warehouse', v_comment, n.id, n.movement_id);
        end if;
      end if;
    end if;
    insert into inv_project_note_events (note_id, company_id, project_id, event, by_user, by_name, capacity, comment, linked_note_id, linked_movement_id)
    values (n.id, n.company_id, n.project_id, 'resolved_corrected', auth.uid(), v_name, 'warehouse', v_comment, v_new, lm.id) returning * into v_event;
  end if;
  v_result := jsonb_build_object('note_id', n.id, 'note_no', n.note_no, 'event', v_event.event, 'by_name', v_event.by_name, 'capacity', v_event.capacity,
                                 'at', v_event.at, 'linked_note_id', v_new, 'replayed', false);
  if p_key is not null then update inv_idempotency set result = v_result where company_id = n.company_id and idem_key = btrim(p_key); end if;
  return v_result;
end;
$$;

-- -----------------------------------------------------------------------------
-- "Waiting for me": the notes THE CALLER can answer right now (current PM, unexpired acting PM, Projects founder), oldest first, minimum fields. For the PM's
-- My Day / Needs me. A person who cannot answer gets no rows, not an error.
-- -----------------------------------------------------------------------------
create or replace function inv_notes_waiting_for_me()
returns table (note_id uuid, note_no text, kind text, project_id uuid, project_ref text, project_name text, waiting_since timestamptz)
language sql stable security definer
set search_path = public
as $$
  select s.note_id, s.note_no, s.kind, n.project_id, n.project_ref, n.project_name, s.pending_since
  from inv_project_note_status s
  join inv_project_notes n on n.id = s.note_id
  where s.awaiting = 'pm' and auth.uid() is not null and proj_can_manage(s.project_id)
  order by s.pending_since, s.note_no;
$$;

-- -----------------------------------------------------------------------------
-- The two movement functions (C2, Option A). Each is the earlier definition (20261201000300) with ONE addition just before the result is stored: a call that is
-- skipped unless the company switched notes on. With the switch off nothing else differs: the same checks, the same rows, the same result.
-- -----------------------------------------------------------------------------

-- Dispatch to a project. With a request, each line must match an active reservation of that request (the reservation's dispatched
-- quantity goes up and it stays active). Without one, the unit or quantity must be unreserved and free from now until the expected return,
-- and another reservation in that period stops the dispatch (nothing is ever displaced).
--   Lines: {"unit_id"} or {"item_id","qty","bin_id","rental_id"}
create or replace function inv_dispatch_to_project(p_company_id uuid, p_location_id uuid, p_project_id uuid, p_key text, p_lines jsonb,
                                                   p_request_id uuid default null, p_expected_return_at timestamptz default null, p_note text default null)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  l inv_locations; pr proj_projects; q inv_requests; h jsonb; v_mid uuid; e jsonb; u inv_units; i inv_items; t record;
  v_exp timestamptz; v_seen uuid[] := '{}'; v_why text; v_res text; v_qty numeric; v_rental uuid; v_free numeric; v_dest uuid; v_covered numeric;
  v_out jsonb := '[]'::jsonb; v_note jsonb;
begin
  perform inv_ctx(p_company_id);
  l := inv_loc(p_company_id, p_location_id);
  perform inv_lines_array(p_lines);
  if p_request_id is not null then
    select * into q from inv_requests where id = p_request_id;
    if q.id is null or q.company_id <> p_company_id then raise exception 'Unknown request' using errcode = '22023'; end if;
    if q.kind <> 'project' or q.project_id is distinct from p_project_id then raise exception 'That request is not for this project' using errcode = '23514'; end if;
    if q.status not in ('submitted', 'in_progress') and not inv_replaying(p_company_id, p_key) then raise exception 'Request % is % and cannot be dispatched against', q.code, q.status using errcode = '23514'; end if;
  end if;
  v_exp := coalesce(p_expected_return_at, q.expected_return_at, q.needed_until);
  if v_exp is null then raise exception 'Say when the equipment is expected back' using errcode = '22023'; end if;
  if v_exp <= now() and not inv_replaying(p_company_id, p_key) then raise exception 'The expected return date must be in the future' using errcode = '22023'; end if;
  h := inv_begin_movement(p_company_id, 'dispatch_project', p_key,
         jsonb_build_object('location', p_location_id, 'project', p_project_id, 'lines', p_lines, 'request', p_request_id, 'expected', p_expected_return_at, 'note', p_note),
         jsonb_build_object('project_id', p_project_id, 'request_id', p_request_id, 'from_location_id', l.id, 'expected_return_at', v_exp, 'note', p_note));
  if (h->>'replay')::boolean then return h->'result'; end if;
  v_mid := (h->>'movement_id')::uuid;
  perform inv_lock_lines(p_lines);
  pr := inv_get_project(p_project_id, true);
  for e in select x from jsonb_array_elements(p_lines) x loop
    if nullif(e->>'unit_id', '') is not null then
      u := inv_unit_lock((e->>'unit_id')::uuid);
      if u.id = any (v_seen) then raise exception '% is listed twice', u.code using errcode = '22023'; end if;
      v_seen := v_seen || u.id;
      i := inv_get_item(u.item_id);
      perform inv_check_sharing(i.company_id, l.company_id);
      perform inv_check_sharing(i.company_id, pr.company_id);
      v_why := inv_unit_block_reason(u, l.id);
      if v_why is not null then raise exception '%', v_why using errcode = '23514'; end if;
      if q.id is not null then
        if inv_reservation_take(q.id, u.item_id, u.id, 1, null) < 1 then
          raise exception '% is not reserved for request %. Reserve it for the request first', u.code, q.code using errcode = '23514';
        end if;
      else
        v_res := inv_unit_reserved_by(u.id, now(), v_exp);
        if v_res is not null then
          raise exception '% is reserved for % in that period. Dispatch it against that request, or choose another unit', u.code, v_res using errcode = '23514';
        end if;
      end if;
      perform inv_unit_move(u.id, 'project', p_project => pr.id, p_expected => v_exp);
      perform inv_ml(v_mid, p_company_id, u.item_id, u.id, 1, 'warehouse', 'project', p_from_loc => l.id, p_from_bin => u.bin_id, p_to_proj => pr.id,
                     p_cond_from => u.condition, p_cond_to => u.condition);
      v_out := v_out || jsonb_build_object('item_id', u.item_id, 'unit_id', u.id, 'code', u.code);
    else
      i := inv_get_item(nullif(e->>'item_id', '')::uuid);
      if i.tracking = 'consumable' then raise exception '% is a consumable. Record its use with Consume, not Dispatch', i.name using errcode = '23514'; end if;
      if i.tracking <> 'quantity' then raise exception '% is tracked unit by unit. Name the units to dispatch', i.name using errcode = '23514'; end if;
      perform inv_check_sharing(i.company_id, l.company_id);
      perform inv_check_sharing(i.company_id, pr.company_id);
      v_qty := inv_check_qty(i.id, (e->>'qty')::numeric);
      v_rental := nullif(e->>'rental_id', '')::uuid;
      if q.id is not null then
        v_covered := inv_reservation_take(q.id, i.id, null, v_qty, l.id);
        if v_covered < v_qty then
          raise exception 'Only % of % is reserved for request % at this location. Reserve the rest first', trim_scale(v_covered), i.name, q.code using errcode = '23514';
        end if;
      else
        v_free := inv_qty_free(i.id, l.id, now(), v_exp, null, v_rental is not null);
        if v_qty > v_free then
          raise exception 'Only % of % is free until %: the rest is not on the shelf or is reserved by another request', trim_scale(v_free), i.name, to_char(v_exp at time zone 'UTC', 'YYYY-MM-DD HH24:MI "UTC"') using errcode = '23514';
        end if;
      end if;
      for t in select * from inv_take_qty(i.id, v_qty, 'warehouse', l.id, nullif(e->>'bin_id', '')::uuid, p_condition => 'good', p_rental => v_rental,
                                           p_rentals => case when v_rental is null then 'owned' else 'only' end, p_where => 'on the shelf here') loop
        v_dest := inv_bal_ensure(i.company_id, i.id, 'project', 'good', p_project => pr.id, p_rental => t.rental_id, p_expected => v_exp);
        perform inv_bal_change(t.balance_id, -t.taken);
        perform inv_bal_change(v_dest, t.taken, v_exp);
        perform inv_ml(v_mid, p_company_id, i.id, null, t.taken, 'warehouse', 'project', p_from_loc => l.id, p_from_bin => t.bin_id, p_to_proj => pr.id,
                       p_from_bal => t.balance_id, p_to_bal => v_dest, p_cond_from => 'good', p_cond_to => 'good');
      end loop;
      v_out := v_out || jsonb_build_object('item_id', i.id, 'qty', v_qty);
    end if;
  end loop;
  if q.id is not null then perform inv_refresh_request_status(q.id); end if;
  -- Dispatch note (launch package 3): inside this same transaction, only for a company that switched it on. A note failure refuses the whole dispatch.
  if inv_project_notes_enabled(p_company_id) then v_note := inv_make_project_note(v_mid); end if;
  return inv_finish_movement(p_company_id, p_key, jsonb_build_object('project_id', pr.id, 'request_id', p_request_id, 'expected_return_at', v_exp,
           'request_status', (select status from inv_requests where id = q.id), 'lines', v_out)
           || case when v_note is null then '{}'::jsonb else jsonb_build_object('note_id', v_note->'note_id', 'note_no', v_note->'note_no') end);
end;
$$;

-- Return from a project; partial returns are normal: whatever is not listed stays on the project. Equipment that was never dispatched to
-- the project is refused. Each line gives a condition (good / fair is available at once; the rest is held).
--   Lines: {"unit_id","condition","bin_id","note"} or {"item_id","qty","condition","bin_id","rental_id","note"}
create or replace function inv_return_from_project(p_company_id uuid, p_location_id uuid, p_project_id uuid, p_key text, p_lines jsonb, p_note text default null)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  l inv_locations; pr proj_projects; h jsonb; v_mid uuid; e jsonb; u inv_units; i inv_items; t record;
  v_seen uuid[] := '{}'; v_cond text; v_bin uuid; v_qty numeric; v_rental uuid; v_dest uuid; v_out jsonb := '[]'::jsonb; v_have numeric; v_note jsonb;
begin
  perform inv_ctx(p_company_id);
  l := inv_loc(p_company_id, p_location_id);
  perform inv_lines_array(p_lines);
  pr := inv_get_project(p_project_id, false);
  h := inv_begin_movement(p_company_id, 'return_project', p_key,
         jsonb_build_object('location', p_location_id, 'project', p_project_id, 'lines', p_lines, 'note', p_note),
         jsonb_build_object('project_id', pr.id, 'to_location_id', l.id, 'note', p_note));
  if (h->>'replay')::boolean then return h->'result'; end if;
  v_mid := (h->>'movement_id')::uuid;
  perform inv_lock_lines(p_lines);
  for e in select x from jsonb_array_elements(p_lines) x loop
    v_bin := nullif(e->>'bin_id', '')::uuid;
    perform inv_check_bin(v_bin, l.id);
    if nullif(e->>'unit_id', '') is not null then
      u := inv_unit_lock((e->>'unit_id')::uuid);
      if u.id = any (v_seen) then raise exception '% is listed twice', u.code using errcode = '22023'; end if;
      v_seen := v_seen || u.id;
      i := inv_get_item(u.item_id);
      perform inv_check_sharing(i.company_id, l.company_id);
      if u.custody_kind <> 'project' or u.project_id is distinct from pr.id then
        raise exception '% was not dispatched to project % (it is %), so it cannot be returned from there', u.code, pr.reference, inv_custody_words(u.custody_kind) using errcode = '23514';
      end if;
      v_cond := inv_valid_condition(e->>'condition');
      perform inv_unit_move(u.id, 'warehouse', l.id, v_bin, p_condition => v_cond);
      perform inv_reservation_return(pr.id, u.item_id, u.id, 1);
      perform inv_ml(v_mid, p_company_id, u.item_id, u.id, 1, 'project', 'warehouse', p_to_loc => l.id, p_to_bin => v_bin, p_from_proj => pr.id,
                     p_cond_from => u.condition, p_cond_to => v_cond, p_note => e->>'note');
      v_out := v_out || jsonb_build_object('item_id', u.item_id, 'unit_id', u.id, 'code', u.code, 'condition', v_cond, 'available', v_cond in ('good', 'fair'));
    else
      i := inv_get_item(nullif(e->>'item_id', '')::uuid);
      perform inv_check_sharing(i.company_id, l.company_id);
      v_qty := inv_check_qty(i.id, (e->>'qty')::numeric);
      v_cond := inv_valid_condition(e->>'condition', true);
      v_rental := nullif(e->>'rental_id', '')::uuid;
      select coalesce(sum(b.qty), 0) into v_have from inv_balances b where b.item_id = i.id and b.holder_kind = 'project' and b.project_id = pr.id;
      if v_have = 0 then raise exception '% was never dispatched to project %, so it cannot be returned from there', i.name, pr.reference using errcode = '23514'; end if;
      for t in select * from inv_take_qty(i.id, v_qty, 'project', p_project => pr.id, p_rental => v_rental,
                                           p_rentals => case when v_rental is null then 'any' else 'only' end, p_where => 'on project ' || pr.reference) loop
        v_dest := inv_bal_ensure(i.company_id, i.id, 'warehouse', v_cond, l.id, v_bin, p_rental => t.rental_id);
        perform inv_bal_change(t.balance_id, -t.taken);
        perform inv_bal_change(v_dest, t.taken);
        perform inv_ml(v_mid, p_company_id, i.id, null, t.taken, 'project', 'warehouse', p_to_loc => l.id, p_to_bin => v_bin, p_from_proj => pr.id,
                       p_from_bal => t.balance_id, p_to_bal => v_dest, p_cond_from => t.condition, p_cond_to => v_cond, p_note => e->>'note');
      end loop;
      perform inv_reservation_return(pr.id, i.id, null, v_qty);
      v_out := v_out || jsonb_build_object('item_id', i.id, 'qty', v_qty, 'condition', v_cond, 'available', v_cond = 'good');
    end if;
  end loop;
  perform inv_refresh_project_requests(pr.id);
  -- Return checklist (launch package 3): inside this same transaction, only for a company that switched it on. A note failure refuses the whole return.
  if inv_project_notes_enabled(p_company_id) then v_note := inv_make_project_note(v_mid); end if;
  return inv_finish_movement(p_company_id, p_key, jsonb_build_object('project_id', pr.id, 'lines', v_out)
           || case when v_note is null then '{}'::jsonb else jsonb_build_object('note_id', v_note->'note_id', 'note_no', v_note->'note_no') end);
end;
$$;

-- -----------------------------------------------------------------------------
-- Privileges: clients read through row-level security only; everything else goes through the functions above.
-- -----------------------------------------------------------------------------
revoke all on table inv_project_notes, inv_project_note_events, inv_project_note_status from anon, authenticated, public;
grant select on table inv_project_notes, inv_project_note_events, inv_project_note_status to authenticated;
revoke all on sequence inv_project_note_events_seq_seq from public, anon, authenticated;

revoke all on function
  inv_project_notes_frozen(), inv_project_notes_enabled(uuid), inv_make_project_note(uuid, uuid), inv_set_project_notes(uuid, boolean),
  inv_ack_project_note(uuid, text, jsonb, text, text, text), inv_resolve_note_difference(uuid, text, text, uuid, text), inv_notes_waiting_for_me()
  from public, anon, authenticated;
grant execute on function
  inv_set_project_notes(uuid, boolean), inv_ack_project_note(uuid, text, jsonb, text, text, text),
  inv_resolve_note_difference(uuid, text, text, uuid, text), inv_notes_waiting_for_me()
  to authenticated;

-- ROLLBACK: supabase/manual-sql/inv_notes_90_rollback.sql (restores the two movement functions and inv_next_code; with notes already issued it keeps the notes and
-- their history and only switches creation off).
-- ==== END MIGRATION 20261217000100_inv_project_notes.sql ====

-- FINAL ASSERTIONS (key objects exist, the notes switch is OFF). Any failure raises an exception and the whole transaction rolls back.
do $batch_check$
declare
  v_bad text;
  v_on bigint;
begin
  select string_agg('migration ' || c.n || ' (' || c.what || ')', '; ' order by c.n::int) into v_bad
  from (values
    ('3', 'deactivation sets is_active; routing skips inactive people; last CEO/CTO protections', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'user_is_active')),
    ('4', 'profiles: the deactivation reason is no longer readable directly; System Administrator function added', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'account_status_details')),
    ('5', 'attendance clock: project-lead candidates function', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'attendance_lead_candidates')),
    ('6', 'Recovery Leave: decider inbox function', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'recovery_decider_inbox')),
    ('7', 'policy status function: role check and no anonymous execute', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'preflight_phase2b_v2_policy_status' and prosrc like '%has_role(''cto'', null, cc.code)%')),
    ('8', 'letters storage: the owning employee reads issued letters only', exists (select 1 from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname = 'letters_select' and qual like '%generated_letters%')),
    ('9', 'approval routing is country-scoped', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'resolve_approver' and prosrc like '%ur.country_code is null or ur.country_code = v_country%')),
    ('10', 'scope decision: two narrow read functions', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'proj_scope_decision_context' and prosrc like '%proj_has_capability%')),
    ('11', 'budget decisions waiting: count function', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'pbx_decisions_waiting_count' and prosrc like '%pbx_can_decide%')),
    ('12', 'blocker: the Project Manager is told who was asked', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'proj_block_task' and prosrc like '%Also tell the Project Manager when someone else was named%')),
    ('13', 'ask-for-access names the people who can grant it', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'module_access_managers' and prosrc like '%One branch per module%')),
    ('14', 'dispatch and return notes: tables, functions, guarded call in the movements, switch column (off)', exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'inv_make_project_note'))
  ) c(n, what, present) where not c.present;
  if v_bad is not null then
    raise exception 'Batch install rolled back: not in place after the install: %', v_bad;
  end if;
  select string_agg('migration ' || a.n || ' function ' || a.name, '; ') into v_bad
  from (values ('3', 'user_is_active'), ('3', 'account_deactivation_blockers'), ('3', 'account_holdings'), ('4', 'account_status_details'), ('5', 'attendance_lead_candidates'), ('6', 'recovery_decider_inbox'), ('10', 'proj_scope_decisions_waiting'), ('10', 'proj_scope_decision_context'), ('11', 'pbx_decisions_waiting_count'), ('13', 'module_access_managers'), ('14', 'inv_project_notes_frozen'), ('14', 'inv_project_notes_enabled'), ('14', 'inv_make_project_note'), ('14', 'inv_ack_project_note'), ('14', 'inv_resolve_note_difference'), ('14', 'inv_notes_waiting_for_me'), ('14', 'inv_set_project_notes')) a(n, name)
  where not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = a.name);
  if v_bad is not null then
    raise exception 'Batch install rolled back: missing function(s): %', v_bad;
  end if;
  if has_column_privilege('authenticated', 'public.profiles', 'status_reason', 'select') or has_column_privilege('anon', 'public.profiles', 'status_reason', 'select') then
    raise exception 'Batch install rolled back: migration 4 did not restrict SELECT on profiles';
  end if;
  if has_function_privilege('anon', 'public.preflight_phase2b_v2_policy_status()'::regprocedure, 'execute') then
    raise exception 'Batch install rolled back: migration 7 left the policy status function callable by anonymous visitors';
  end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'inv_company_settings' and column_name = 'project_notes_enabled') then
    raise exception 'Batch install rolled back: the notes switch column is missing';
  end if;
  execute 'select count(*) from public.inv_company_settings where project_notes_enabled is not false' into v_on;
  if v_on <> 0 then
    raise exception 'Batch install rolled back: the dispatch / return notes switch is not OFF for every company (% company row(s))', v_on;
  end if;
  if to_regclass('public.inv_project_notes') is null or to_regclass('public.inv_project_note_events') is null or to_regclass('public.inv_project_note_status') is null then
    raise exception 'Batch install rolled back: a dispatch / return note table or view is missing';
  end if;
end
$batch_check$;

